          `Notes: ${notes || '-'}\n` +
          `Waktu: ${tgTime} WIB`
        );
        // ── Log activity ────────────────────────────────────────────────────
        logActivity(order?.insurer_id ?? null, rt.order_id, 'DECISION_SUBMITTED', { action, notes, via: 'review_token' });
        return json({ data: { success: true, order_status: orderStatus, action } });
