    case 'insurer_upload_policy': {
        const token = String(params.token ?? '');
        const orderId = String(params.order_id ?? '');
        const policyDocumentUrl = String(params.policy_document_url ?? '');
        const policyNumber = String(params.policy_number ?? '');
        if (!token || !orderId || !policyDocumentUrl) return json({ error: 'token, order_id, policy_document_url required' }, 400);
        // Validate insurer auth token
        const { data: authToken, error: authErr } = await db.from('sp_insurer_auth_tokens')
          .select('id, insurer_id, expires_at')
          .eq('token', token)
          .maybeSingle();
        if (authErr) return json({ error: authErr.message }, 400);
        if (!authToken) return json({ error: 'Invalid token' }, 404);
        if (new Date(authToken.expires_at) < new Date()) return json({ error: 'Token expired' }, 410);
        // Verify order belongs to this insurer
        const { data: order, error: ordErr } = await db.from('sp_policy_orders')
          .select('id, order_number, insurer_id, status, client_name, agent_id, client_id')
          .eq('id', orderId)
          .eq('insurer_id', authToken.insurer_id)
          .maybeSingle();
        if (ordErr) return json({ error: ordErr.message }, 400);
        if (!order) return json({ error: 'Order not found or not assigned to your insurer' }, 404);
        // Update order
        const ts = new Date().toISOString();
        const { data: updated, error: updErr } = await db.from('sp_policy_orders').update({
          policy_document_url: policyDocumentUrl,
          policy_number: policyNumber || null,
          status: 'ISSUED',
          issued_at: ts,
          updated_at: ts,
        }).eq('id', orderId).select().maybeSingle();
        if (updErr) return json({ error: updErr.message }, 400);
        // Notifications
        db.from('sp_admin_notifications').insert({
          type: 'POLICY_ISSUED',
          title: 'Polis Diterbitkan oleh Insurer',
          body: `${order.order_number} — ${order.client_name}: polis ${policyNumber || '(no number)'} telah diterbitkan.`,
          order_id: orderId,
          read: false,
          metadata: { order_id: orderId, policy_number: policyNumber, insurer_id: authToken.insurer_id },
        }).then(() => {}, () => {});
        // The customer is the one who most needs this one: their policy
        // document is now downloadable from /custapp. Previously only the
        // agent was told.
        {
          const recipients = [...new Set([order.agent_id, order.client_id].filter(Boolean))];
          for (const recipient of recipients) {
            db.from('sp_notifications').insert({
              agent_id: recipient,
              type: 'POLICY_ISSUED',
              title: 'Polis Diterbitkan!',
              body: `${order.order_number}: polis ${policyNumber || ''} sudah diterbitkan oleh insurer.`,
              read: false,
              metadata: { order_id: orderId, policy_number: policyNumber },
            }).then(() => {}, () => {});
          }
        }
        // ── Log activity ────────────────────────────────────────────────────
        logActivity(authToken.insurer_id, orderId, 'POLICY_UPLOADED', { policy_number: policyNumber, document_url: policyDocumentUrl });
        return json({ data: { success: true, order: updated } });
      }

    default:
      return null; // Not handled by this module
  }
}

// marketing.ts — CRM & KPI untuk karyawan marketing/sales (Fase 1)
//
// Dibangun lebih dulu dari Fase 0 (tulang belakang produksi) dengan sengaja:
// pipeline rekrutmen dan follow-up tidak butuh data produksi sama sekali.
// Kolom ANGKA produksi (premi, komisi, status bayar) BELUM dimunculkan di sini
// karena sumbernya belum sah — per 21 Okt 2026 sp_payments 0 baris,
// sp_commissions 0 dari 13 tertaut order, policy_number 0 dari 5 terisi.
// Memunculkannya sekarang berarti menampilkan angka yang terlihat meyakinkan
// dan salah, dan untuk aplikasi uang itu lebih berbahaya daripada kosong.
//
// Yang DISAJIKAN sekarang dan sudah nyata: tahap rekrutmen, umur per tahap,
// apakah seorang agen pernah berproduksi sama sekali, dan janji follow-up yang
// lewat tanggal.
import type { GatewayContext, ActionResult } from './types.ts';

const json = (body: unknown, status = 200): ActionResult => ({ status, body });

const MARKETING = 'MARKETING';

/** Subtree seorang marketing: dirinya + marketing di bawahnya (L2). */
async function subtreeIds(db: any, meId: string): Promise<string[]> {
  const { data } = await db
    .from('sp_users')
    .select('id')
    .eq('marketing_parent_id', meId)
    .eq('role', MARKETING);
  return [meId, ...(data ?? []).map((r: any) => r.id)];
}

/**
 * Siapa yang boleh dilihat pemanggil.
 * - ADMIN: siapa pun (handlerIds = null berarti "tanpa batas")
 * - MARKETING: hanya agen di subtree-nya
 * - lainnya: tidak boleh
 *
 * Batasnya dihitung DI SINI dari peran yang sudah diverifikasi, bukan dari
 * params. Itu aturan yang sama dengan agent_id/client_id di modul lain.
 */
async function scope(ctx: GatewayContext): Promise<{ handlerIds: string[] | null } | null> {
  const { db, caller } = ctx;
  if (caller.isAdmin) return { handlerIds: null };
  if ((caller.role ?? '') !== MARKETING || !caller.spUser) return null;
  return { handlerIds: await subtreeIds(db, caller.spUser.id) };
}

/** Tahap pipeline, diturunkan dari kolom yang SUDAH ada — bukan status baru. */
function stageOf(u: any, pernahProduksi: boolean): string {
  if (pernahProduksi) return 'PRODUKTIF';
  if (u.verified === true || String(u.identity_status ?? '').toUpperCase() === 'APPROVED') return 'TERVERIFIKASI';
  if (u.identity_submitted_at) return 'DOKUMEN';
  return 'DAFTAR';
}

const hariSejak = (iso: string | null | undefined): number | null =>
  iso ? Math.floor((Date.now() - Date.parse(iso)) / 86_400_000) : null;

export async function handleMarketingAction(
  action: string,
  ctx: GatewayContext,
): Promise<ActionResult | null> {
  const { db, params, caller } = ctx;

  switch (action) {
    // ── Daftar agen yang dipegang ────────────────────────────────────────────
    case 'marketing_list_agents': {
      const s = await scope(ctx);
      if (!s) return json({ error: 'Forbidden: marketing only' }, 403);

      let q = db
        .from('sp_users')
        .select('id, name, email, phone, agent_code, tier, verified, identity_status, identity_submitted_at, created_at, handler_id, handler_assigned_at')
        .eq('role', 'AGENT')
        .order('created_at', { ascending: false })
        .limit(Math.min(Number(params.limit ?? 200), 500));

      if (s.handlerIds) q = q.in('handler_id', s.handlerIds);
      else if (params.handler_id) q = q.eq('handler_id', String(params.handler_id));

      const { data: agents, error } = await q;
      if (error) return json({ error: error.message }, 400);

      const ids = (agents ?? []).map((a: any) => a.id);
      // Satu kueri untuk semua agen, bukan N+1.
      const { data: orders } = ids.length
        ? await db.from('sp_policy_orders')
            .select('agent_id, created_at')
            .in('agent_id', ids)
            .is('deleted_at', null)
        : { data: [] };
      const { data: acts } = ids.length
        ? await db.from('sp_marketing_activities')
            .select('agent_id, created_at')
            .in('agent_id', ids)
            .order('created_at', { ascending: false })
        : { data: [] };

      const orderTerakhir = new Map<string, string>();
      for (const o of orders ?? []) {
        const prev = orderTerakhir.get(o.agent_id);
        if (!prev || Date.parse(o.created_at) > Date.parse(prev)) orderTerakhir.set(o.agent_id, o.created_at);
      }
      const aktivitasTerakhir = new Map<string, string>();
      for (const a of acts ?? []) if (a.agent_id && !aktivitasTerakhir.has(a.agent_id)) aktivitasTerakhir.set(a.agent_id, a.created_at);

      const rows = (agents ?? []).map((a: any) => {
        const last = orderTerakhir.get(a.id) ?? null;
        return {
          ...a,
          stage: stageOf(a, !!last),
          // Metrik yang paling sering disembunyikan dashboard, dan paling
          // menentukan: 23 agen terdaftar, 2 pernah berproduksi (21 Okt 2026).
          pernah_produksi: !!last,
          hari_sejak_order_terakhir: hariSejak(last),
          hari_sejak_aktivitas: hariSejak(aktivitasTerakhir.get(a.id) ?? null),
          umur_hari: hariSejak(a.created_at),
        };
      });

      return json({ data: rows });
    }

    // ── Ringkasan dashboard: pipeline + antrean ─────────────────────────────
    case 'marketing_dashboard_summary': {
      const s = await scope(ctx);
      if (!s) return json({ error: 'Forbidden: marketing only' }, 403);

      let q = db
        .from('sp_users')
        .select('id, verified, identity_status, identity_submitted_at, created_at')
        .eq('role', 'AGENT');
      if (s.handlerIds) q = q.in('handler_id', s.handlerIds);
      const { data: agents, error } = await q;
      if (error) return json({ error: error.message }, 400);

      const ids = (agents ?? []).map((a: any) => a.id);
      const { data: orders } = ids.length
        ? await db.from('sp_policy_orders').select('agent_id').in('agent_id', ids).is('deleted_at', null)
        : { data: [] };
      const produktif = new Set((orders ?? []).map((o: any) => o.agent_id));

      const pipeline: Record<string, { jumlah: number; mandek_14h: number }> = {
        DAFTAR: { jumlah: 0, mandek_14h: 0 },
        DOKUMEN: { jumlah: 0, mandek_14h: 0 },
        TERVERIFIKASI: { jumlah: 0, mandek_14h: 0 },
        PRODUKTIF: { jumlah: 0, mandek_14h: 0 },
      };
      for (const a of agents ?? []) {
        const st = stageOf(a, produktif.has(a.id));
        pipeline[st].jumlah += 1;
        // Umur di TAHAP, bukan umur akun: itu yang menunjukkan kemandekan.
        const sejak = st === 'DOKUMEN' ? a.identity_submitted_at : a.created_at;
        if (st !== 'PRODUKTIF' && (hariSejak(sejak) ?? 0) > 14) pipeline[st].mandek_14h += 1;
      }

      // Janji follow-up yang sudah lewat tanggal — ini yang dibuka tiap pagi.
      let fq = db
        .from('sp_marketing_activities')
        .select('id', { count: 'exact', head: true })
        .not('next_action_at', 'is', null)
        .lt('next_action_at', new Date().toISOString());
      if (s.handlerIds) fq = fq.in('marketing_id', s.handlerIds);
      const { count: telatCount } = await fq;

      let uq = db.from('sp_users').select('id', { count: 'exact', head: true })
        .eq('role', 'AGENT').is('handler_id', null);
      const { count: tanpaHandler } = await uq;

      return json({
        data: {
          pipeline,
          total_agen: (agents ?? []).length,
          belum_pernah_produksi: (agents ?? []).length - produktif.size,
          follow_up_telat: telatCount ?? 0,
          agen_tanpa_handler: tanpaHandler ?? 0,
          catatan_produksi: 'Angka premi/komisi/status bayar belum ditampilkan: sumbernya belum sah sampai Fase 0 selesai.',
        },
      });
    }

    // ── Detail satu agen ────────────────────────────────────────────────────
    case 'marketing_agent_detail': {
      const s = await scope(ctx);
      if (!s) return json({ error: 'Forbidden: marketing only' }, 403);
      const agentId = String(params.agent_id ?? '');
      if (!agentId) return json({ error: 'agent_id required' }, 400);

      const { data: agent, error } = await db
        .from('sp_users')
        .select('id, name, email, phone, agent_code, tier, verified, identity_status, identity_submitted_at, created_at, handler_id, handler_assigned_at')
        .eq('id', agentId)
        .eq('role', 'AGENT')
        .maybeSingle();
      if (error) return json({ error: error.message }, 400);
      if (!agent) return json({ error: 'Agent not found' }, 404);
      // Batas kepemilikan ditegakkan SETELAH baris dibaca, dari handler_id
      // baris itu sendiri — bukan dari params.
      if (s.handlerIds && !s.handlerIds.includes(agent.handler_id ?? '')) {
        return json({ error: 'Forbidden: bukan agen Anda' }, 403);
      }

      const { data: activities } = await db
        .from('sp_marketing_activities')
        .select('*')
        .eq('agent_id', agentId)
        .order('created_at', { ascending: false })
        .limit(100);

      const { data: handlerHistory } = await db
        .from('sp_agent_handler_history')
        .select('*')
        .eq('agent_id', agentId)
        .order('valid_from', { ascending: false });

      const { data: orders } = await db
        .from('sp_policy_orders')
        .select('id, order_number, product_name, status, total_premium, commission_amount, start_date, end_date, policy_number, insurer_name, created_at')
        .eq('agent_id', agentId)
        .is('deleted_at', null)
        .order('created_at', { ascending: false })
        .limit(50);

      return json({ data: { agent, activities: activities ?? [], handler_history: handlerHistory ?? [], orders: orders ?? [] } });
    }

    // ── Catat aktivitas / follow-up ─────────────────────────────────────────
    case 'marketing_log_activity': {
      if ((caller.role ?? '') !== MARKETING || !caller.spUser) {
        return json({ error: 'Forbidden: marketing only' }, 403);
      }
      const kind = String(params.kind ?? '').toUpperCase();
      if (!['CALL', 'WA', 'VISIT', 'TRAINING', 'OTHER'].includes(kind)) {
        return json({ error: 'kind tidak valid' }, 400);
      }
      const agentId = params.agent_id ? String(params.agent_id) : null;
      const prospectName = String(params.prospect_name ?? '').trim() || null;
      if (!agentId && !prospectName) return json({ error: 'agent_id atau prospect_name wajib' }, 400);

      // Hanya boleh mencatat untuk agen di subtree sendiri.
      if (agentId) {
        const ids = await subtreeIds(db, caller.spUser.id);
        const { data: agent } = await db.from('sp_users').select('id, handler_id').eq('id', agentId).maybeSingle();
        if (!agent) return json({ error: 'Agent not found' }, 404);
        if (!ids.includes(agent.handler_id ?? '')) return json({ error: 'Forbidden: bukan agen Anda' }, 403);
      }

      const { data, error } = await db
        .from('sp_marketing_activities')
        .insert({
          marketing_id: caller.spUser.id,   // dari pemanggil terverifikasi, bukan params
          agent_id: agentId,
          prospect_name: prospectName,
          kind,
          outcome: String(params.outcome ?? '').slice(0, 500) || null,
          note: String(params.note ?? '').slice(0, 2000) || null,
          next_action: String(params.next_action ?? '').slice(0, 500) || null,
          next_action_at: params.next_action_at ? String(params.next_action_at) : null,
        })
        .select()
        .single();
      if (error) return json({ error: error.message }, 400);
      return json({ data });
    }

    // ── Antrean tindakan: janji yang lewat tanggal ──────────────────────────
    case 'marketing_list_activities': {
      const s = await scope(ctx);
      if (!s) return json({ error: 'Forbidden: marketing only' }, 403);

      let q = db
        .from('sp_marketing_activities')
        .select('*')
        .order('created_at', { ascending: false })
        .limit(Math.min(Number(params.limit ?? 200), 500));
      if (s.handlerIds) q = q.in('marketing_id', s.handlerIds);
      if (params.agent_id) q = q.eq('agent_id', String(params.agent_id));
      if (params.hanya_telat === true) {
        q = q.not('next_action_at', 'is', null).lt('next_action_at', new Date().toISOString());
      }
      const { data, error } = await q;
      if (error) return json({ error: error.message }, 400);
      return json({ data });
    }

    // ── Agen tanpa handler: antrean penugasan ───────────────────────────────
    case 'marketing_list_unassigned': {
      const s = await scope(ctx);
      if (!s) return json({ error: 'Forbidden: marketing only' }, 403);
      const { data, error } = await db
        .from('sp_users')
        .select('id, name, email, phone, agent_code, verified, identity_status, created_at')
        .eq('role', 'AGENT')
        .is('handler_id', null)
        .order('created_at', { ascending: false })
        .limit(200);
      if (error) return json({ error: error.message }, 400);
      return json({ data: (data ?? []).map((a: any) => ({ ...a, umur_hari: hariSejak(a.created_at) })) });
    }

    // ── Penugasan manual (CMS) ──────────────────────────────────────────────
    // ADMIN saja. Seorang marketing tidak boleh menugaskan agen ke dirinya
    // sendiri: itu akan membuat kepemilikan — dan nanti komisi override —
    // bisa diklaim sendiri.
    case 'marketing_assign_agent': {
      if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
      const agentId = String(params.agent_id ?? '');
      const handlerId = params.handler_id ? String(params.handler_id) : null;
      if (!agentId) return json({ error: 'agent_id required' }, 400);

      const { data: agent } = await db.from('sp_users').select('id, role').eq('id', agentId).maybeSingle();
      if (!agent) return json({ error: 'Agent not found' }, 404);
      if (String(agent.role ?? '').toUpperCase() !== 'AGENT') {
        return json({ error: 'Target bukan agen' }, 400);
      }
      if (handlerId) {
        const { data: h } = await db.from('sp_users').select('id, role').eq('id', handlerId).maybeSingle();
        if (!h) return json({ error: 'Marketing not found' }, 404);
        if (String(h.role ?? '').toUpperCase() !== MARKETING) {
          return json({ error: 'Handler harus berperan MARKETING' }, 400);
        }
      }

      // Riwayatnya ditulis oleh trigger sp_users_handler_change, bukan di sini.
      const { data, error } = await db
        .from('sp_users')
        .update({
          handler_id: handlerId,
          handler_assigned_by: caller.spUser?.id ?? null,
          handler_assigned_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        })
        .eq('id', agentId)
        .select('id, name, handler_id, handler_assigned_at')
        .maybeSingle();
      if (error) return json({ error: error.message }, 400);
      return json({ data });
    }

    // ── Agen membaca pendampingnya sendiri ──────────────────────────────────
    // Hanya kontak publik (nama, telepon, foto). Agen TIDAK boleh melihat
    // email internal, target, atau struktur marketing, dan tidak boleh
    // mengubah handler-nya sendiri — tidak ada aksi tulis untuk itu di sini.
    case 'get_my_handler': {
      if (!caller.spUser) return json({ data: null });
      const handlerId = caller.spUser.handler_id;
      if (!handlerId) return json({ data: null });
      const { data, error } = await db
        .from('sp_users')
        .select('id, name, phone, profile_photo_url')
        .eq('id', handlerId)
        .maybeSingle();
      if (error) return json({ error: error.message }, 400);
      return json({ data: data ?? null });
    }

    // ── Master dashboard: satu baris per marketing ──────────────────────────
    case 'admin_marketing_overview': {
      if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);

      const { data: mkt, error } = await db
        .from('sp_users')
        .select('id, name, email, monthly_target, marketing_parent_id, created_at')
        .eq('role', MARKETING)
        .order('name');
      if (error) return json({ error: error.message }, 400);

      const { data: agents } = await db
        .from('sp_users')
        .select('id, handler_id, verified')
        .eq('role', 'AGENT')
        .not('handler_id', 'is', null);
      const { data: orders } = await db
        .from('sp_policy_orders')
        .select('agent_id')
        .is('deleted_at', null);

      const produktif = new Set((orders ?? []).map((o: any) => o.agent_id));
      const perHandler = new Map<string, { agen: number; produktif: number }>();
      for (const a of agents ?? []) {
        const k = a.handler_id as string;
        const cur = perHandler.get(k) ?? { agen: 0, produktif: 0 };
        cur.agen += 1;
        if (produktif.has(a.id)) cur.produktif += 1;
        perHandler.set(k, cur);
      }

      return json({
        data: (mkt ?? []).map((m: any) => ({
          ...m,
          jumlah_agen: perHandler.get(m.id)?.agen ?? 0,
          agen_produktif: perHandler.get(m.id)?.produktif ?? 0,
        })),
      });
    }

    default:
      return null;
  }
}

// misc.ts — 4 actions
// Auto-generated from data-gateway/index.ts split
import type { GatewayContext, ActionResult } from './types.ts';
import { wrapUserContent, UNTRUSTED_INPUT_NOTICE } from '../../_shared/promptSafety.ts';

// json() helper — returns ActionResult (main index.ts converts to Response)
const json = (body: unknown, status = 200): ActionResult => ({ status, body });

export async function handleMiscAction(action: string, ctx: GatewayContext): Promise<ActionResult | null> {
  const { db, params, caller, sendTelegram, logActivity, checkRateLimit, RESEND_KEY } = ctx;

  switch (action) {
    case 'pathy_chat': {
        if (!caller.spUser) return json({ error: 'No profile' }, 403);
        const ANTHROPIC_KEY = Deno.env.get('ANTHROPIC_API_KEY') ?? '';
        if (!ANTHROPIC_KEY) return json({ error: 'AI not configured' }, 503);
        const message = (params?.message as string | undefined)?.trim() ?? '';
        if (!message) return json({ error: 'No message provided' }, 400);
        const chatAllowed = await checkRateLimit(`user:${caller.spUser.id}`, 20);
        if (!chatAllowed) return json({ error: 'Terlalu banyak pesan. Coba lagi dalam 1 jam.' }, 429);
        const [ordersRes, claimsRes] = await Promise.all([
          db.from('sp_policy_orders').select('order_number,product_name,status,created_at').eq('client_id', caller.spUser.id).limit(10),
          db.from('sp_claims').select('claim_number,status,created_at').eq('user_id', caller.spUser.id).limit(5),
        ]);
        const policySummary = (ordersRes.data ?? [])
          .map((o: any) => `- ${o.order_number}: ${o.product_name} (${o.status})`)
          .join('\n') || 'No active policies.';
        const claimSummary = (claimsRes.data ?? [])
          .map((c: any) => `- ${c.claim_number}: ${c.status}`)
          .join('\n') || 'No claims.';
        // The caller's own display name is user-editable, so it never goes
        // into the system prompt — only the role (a fixed enum, not free
        // text) is safe to interpolate here.
        const systemPrompt = `You are Pathy, a friendly AI assistant for SurePath, an Indonesian InsurTech platform.
You are speaking with a user with role: ${caller.role ?? 'CUSTOMER'}.
You have READ-ONLY access to their data. You CANNOT modify, create, or delete anything.

User's policies:
${policySummary}

User's claims:
${claimSummary}

Guidelines:
- Be warm, concise, helpful. Max 3 sentences unless detailed steps are needed.
- Reply in the same language the user writes in (Bahasa Indonesia or English).
- For billing changes, cancellations, or urgent matters, recommend contacting an agent via WhatsApp.
- Never fabricate policy numbers, amounts, or dates not shown above.

${UNTRUSTED_INPUT_NOTICE}`;
        const aiRes = await fetch('https://api.anthropic.com/v1/messages', {
          method: 'POST',
          headers: {
            'x-api-key': ANTHROPIC_KEY,
            'anthropic-version': '2023-06-01',
            'content-type': 'application/json',
          },
          body: JSON.stringify({
            model: 'claude-haiku-4-5-20251001',
            max_tokens: 512,
            system: systemPrompt,
            messages: [{ role: 'user', content: wrapUserContent(message) }],
          }),
        });
        if (!aiRes.ok) return json({ error: `AI service error: ${aiRes.status}` }, 502);
        const aiJson = await aiRes.json();
        const reply = aiJson.content?.[0]?.text ?? 'Maaf, tidak bisa memproses permintaan saat ini.';
        return json({ data: { reply } });
      }

    case 'admin_update_b2b_submission': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        const subId = String(params.submission_id ?? '');
        if (!subId) return json({ error: 'submission_id required' }, 400);
        const ALLOWED = ['status', 'notes', 'quoted_premium', 'assigned_to'];
        const updates: Record<string, unknown> = { updated_at: new Date().toISOString() };
        for (const k of ALLOWED) { if (k in params) updates[k] = params[k]; }
        const { data, error } = await db.from('sp_b2b_submissions').update(updates).eq('id', subId).select().maybeSingle();
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'admin_create_b2b_quote': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        const { data, error } = await db.from('sp_b2b_quotes').insert({
          submission_id: String(params.submission_id ?? ''),
          insurer_id: String(params.insurer_id ?? ''),
          premium: Number(params.premium ?? 0),
          coverage_details: params.coverage_details ?? {},
          status: 'PENDING',
        }).select().single();
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'admin_update_life_application': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        const appId = String(params.application_id ?? '');
        if (!appId) return json({ error: 'application_id required' }, 400);
        const updates: Record<string, unknown> = { updated_at: new Date().toISOString() };
        if (params.status) updates.status = String(params.status);
        if (params.notes !== undefined) updates.insurer_notes = params.notes;
        if (params.policy_number !== undefined) updates.policy_number = params.policy_number;
        const { data, error } = await db.from('sp_life_applications').update(updates).eq('id', appId).select().maybeSingle();
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    // ─── save_quote — agent saves their quote ──────────────────────────────
    case 'save_quote': {
        if (!caller.spUser) return json({ error: 'No profile' }, 403);
        // FIX v1.50.0: use canonical sp_users.id so the quote shows up in the
        // agent's own list (which queries by sp_users.id).
        // FIX: the payload column is `quote_data` (NOT NULL). This wrote to
        // `details`, which does not exist on sp_quotes — so every save was
        // rejected and the agent's quote builder reported a save failure.
        const { data, error } = await db.from('sp_quotes').insert({
          agent_id: caller.ownerId,
          client_id: params.client_id ?? null,
          client_name: String(params.client_name ?? ''),
          product_type: String(params.product_type ?? 'CAR'),
          status: String(params.status ?? 'SENT'),
          premium_estimate: Number(params.premium_estimate ?? 0),
          quote_data: params.quote_data ?? params.details ?? {},
        }).select().single();
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    default:
      return null; // Not handled by this module
  }
}

// notifications.ts — 8 actions
// Auto-generated from data-gateway/index.ts split
import type { GatewayContext, ActionResult } from './types.ts';

// json() helper — returns ActionResult (main index.ts converts to Response)
const json = (body: unknown, status = 200): ActionResult => ({ status, body });

export async function handleNotificationsAction(action: string, ctx: GatewayContext): Promise<ActionResult | null> {
  const { db, params, caller, sendTelegram, logActivity, checkRateLimit, RESEND_KEY } = ctx;

  switch (action) {
    // FIX v1.50.0: notifications are inserted with agent_id = sp_users.id
    // (order flows) — reads/updates must match both owner ids or legacy
    // accounts never see their notifications.
    case 'get_my_notifications': {
        const { data, error } = await db
          .from('sp_notifications')
          .select('*')
          .in('agent_id', caller.ownerIds)
          .order('created_at', { ascending: false })
          .limit(50);
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'mark_my_notification_read': {
        if (!caller.spUser) return json({ error: 'No profile' }, 403);
        const notifId = String(params.notification_id ?? '');
        if (!notifId) return json({ error: 'notification_id required' }, 400);
        const { error } = await db.from('sp_notifications')
          .update({ read: true }).eq('id', notifId).in('agent_id', caller.ownerIds);
        if (error) return json({ error: error.message }, 400);
        return json({ data: { success: true } });
      }

    case 'mark_all_my_notifications_read': {
        if (!caller.spUser) return json({ error: 'No profile' }, 403);
        const { error } = await db.from('sp_notifications')
          .update({ read: true }).in('agent_id', caller.ownerIds).eq('read', false);
        if (error) return json({ error: error.message }, 400);
        return json({ data: { success: true } });
      }

    case 'create_notification': {
        if (!caller.spUser) return json({ error: 'No profile' }, 403);
        // FIX: previously this overwrote agent_id with caller.authId, which silently
        // misrouted every admin→agent notification to the admin's own feed.
        // Now: if caller is admin/staff AND params.agent_id is provided and points to someone else,
        // use that target. Otherwise default to self (for user-self notifications).
        const targetAgentId = (caller.isAdmin && params.agent_id && !caller.ownerIds.includes(String(params.agent_id)))
          ? String(params.agent_id)
          : caller.ownerId;
        const { data, error } = await db.from('sp_notifications').insert({
          agent_id: targetAgentId,
          type: String(params.type ?? 'SYSTEM'),
          title: String(params.title ?? ''),
          body: String(params.body ?? ''),
          read: false,
          metadata: params.metadata ?? null,
          order_id: params.order_id ?? null,
        }).select().maybeSingle();
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    // ─── New: explicit admin→user notification (fixes mass-assignment + agent_id corruption) ──
    // Admin/staff-only. Strict allowlist of fields. Always uses params.agent_id as target.
    case 'admin_create_user_notification': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        if (!params.agent_id) return json({ error: 'agent_id required' }, 400);
        const { data, error } = await db.from('sp_notifications').insert({
          agent_id: String(params.agent_id),
          type: String(params.type ?? 'SYSTEM'),
          title: String(params.title ?? '').slice(0, 200),
          body: String(params.body ?? '').slice(0, 1000),
          read: false,
          metadata: params.metadata ?? null,
          order_id: params.order_id ?? null,
        }).select().maybeSingle();
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'admin_list_notifications': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        let q = db.from('sp_admin_notifications').select('*').order('created_at', { ascending: false }).limit(Number(params.limit ?? 50));
        if (params.unread_only) q = q.eq('read', false);
        const { data, error } = await q;
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'admin_mark_notification_read': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        if (!params.notification_id) return json({ error: 'notification_id required' }, 400);
        await db.from('sp_admin_notifications').update({ read: true }).eq('id', params.notification_id);
        return json({ data: { success: true } });
      }

    case 'admin_create_notification': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        // FIX: previously spread {...params, read: false} — mass-assignment risk.
        // Now use explicit allowlist (defense in depth).
        const { data, error } = await db.from('sp_admin_notifications').insert({
          type: String(params.type ?? 'SYSTEM'),
          title: String(params.title ?? '').slice(0, 200),
          body: String(params.body ?? '').slice(0, 1000),
          read: false,
          metadata: params.metadata ?? null,
        }).select().maybeSingle();
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'admin_mark_all_notifications_read': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        const { error: updErr } = await db.from('sp_admin_notifications').update({ read: true }).eq('read', false);
        if (updErr) return json({ error: updErr.message }, 400);
        return json({ data: { success: true } });
      }

    default:
      return null; // Not handled by this module
  }
}

