        ]);
        const payments = (paymentsRes.data ?? []) as any[];
        const totalPaid = payments.filter((p: any) => p.status === 'PAID').length;
        const totalPendingPayments = payments.filter((p: any) => p.status === 'PENDING').length;
        return json({
          data: {
            pendingOrders:       pendingOrdersRes.count ?? 0,
            pendingClaims:       pendingClaimsRes.count ?? 0,
            pendingWithdrawals:  pendingWithdrawalsRes.count ?? 0,
            pendingAgents:       pendingAgentsRes.count ?? 0,
            unreadNotifications: unreadNotifsRes.count ?? 0,
            paidPayments:        totalPaid,
            pendingPayments:     totalPendingPayments,
          },
        });
      }

    case 'admin_list_orders': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        let q = db.from('sp_policy_orders').select('*').is('deleted_at', null).order('created_at', { ascending: false }).limit(Number(params.limit ?? 500));
        if (params.status) q = q.eq('status', String(params.status));
        const { data, error } = await q;
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'admin_get_order': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        if (!params.order_id) return json({ error: 'order_id required' }, 400);
        const { data, error } = await db.from('sp_policy_orders').select('*').eq('id', String(params.order_id)).maybeSingle();
        if (error) return json({ error: error.message }, 400);
        if (!data) return json({ error: 'Order not found' }, 404);
        return json({ data });
      }

    case 'admin_update_order': {
        // FIX: removed `caller.role !== 'INSURER'` branch (no such role exists in sp_users).
        // Now strictly admin-only. Insurer mutations route through insurer_upload_policy / submit_insurer_decision.
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        if (!params.order_id || !params.status) return json({ error: 'order_id and status required' }, 400);
        const ALLOWED_STATUS = ['SUBMITTED', 'UNDER_REVIEW', 'APPROVED', 'REJECTED', 'ISSUED', 'CANCELLED'];
        if (!ALLOWED_STATUS.includes(String(params.status))) return json({ error: 'Invalid status' }, 400);
        const ALLOWED = ['status', 'reviewer_notes', 'policy_number', 'policy_document_url', 'sp_policy_id', 'reviewed_at', 'issued_at'];
        const updates: Record<string, unknown> = { updated_at: new Date().toISOString() };
        for (const k of ALLOWED) { if (k in params && k !== 'order_id') updates[k] = params[k]; }
        const s = String(params.status);
        if (['UNDER_REVIEW', 'APPROVED', 'REJECTED'].includes(s) && !updates.reviewed_at) updates.reviewed_at = new Date().toISOString();
        if (s === 'ISSUED' && !updates.issued_at) updates.issued_at = new Date().toISOString();

        // Fetch current row for notification targeting
        const { data: current } = await db.from('sp_policy_orders')
          .select('id, agent_id, client_name, order_number, status, total_premium')
          .eq('id', String(params.order_id))
          .maybeSingle();

        const { data, error } = await db.from('sp_policy_orders').update(updates).eq('id', params.order_id).select().maybeSingle();
        if (error) return json({ error: error.message }, 400);

        // FIX: send notifications on status changes (previously silent — customer/agent never told about approval/rejection)
        const cur = current as any;
        if (cur && cur.status !== s) {
          const statusLabels: Record<string, string> = {
            SUBMITTED:    'Diajukan',
            UNDER_REVIEW: 'Sedang Ditinjau',
            APPROVED:     'Disetujui',
            REJECTED:     'Ditolak',
            ISSUED:       'Polis Diterbitkan',
            CANCELLED:    'Dibatalkan',
          };
          const newLabel = statusLabels[s] ?? s;

          // Notify the agent (whoever is recorded as agent_id on the order)
          if (cur.agent_id) {
            db.from('sp_notifications').insert({
              agent_id: String(cur.agent_id),
              type: s === 'ISSUED' ? 'POLICY_ISSUED' : s === 'REJECTED' ? 'POLICY_REJECTED' : 'ORDER_UPDATE',
              title: `Order ${newLabel}`,
              body: `Order ${cur.order_number ?? ''} (${cur.client_name ?? ''}) telah ${newLabel}.${params.reviewer_notes ? ` Catatan: ${String(params.reviewer_notes).slice(0, 200)}` : ''}`,
              read: false,
              metadata: { order_id: cur.id, status: s, reviewer_notes: params.reviewer_notes ?? null },
            }).then(() => {}, () => {});
          }

          // For REJECTED/CANCELLED, also insert an admin notification so it shows up in the operations feed
          if (s === 'REJECTED' || s === 'CANCELLED') {
            db.from('sp_admin_notifications').insert({
              type: s === 'REJECTED' ? 'ORDER_REJECTED' : 'ORDER_CANCELLED',
              title: `Order ${newLabel}`,
              body: `Order ${cur.order_number ?? ''} (${cur.client_name ?? ''}) telah ${newLabel} oleh ${caller.spUser?.name ?? 'admin'}.`,
              read: false,
              metadata: { order_id: cur.id, status: s, actor_id: caller.authId },
            }).then(() => {}, () => {});
          }
        }
        return json({ data });
      }

    case 'admin_list_payments': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        const { data, error } = await db.from('sp_payments')
          .select('*, sp_policy_orders!order_id(order_number, client_name, product_name)')
          .is('deleted_at', null)
          .order('created_at', { ascending: false })
          .limit(Number(params.limit ?? 200));
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'admin_transaksi_overview': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        const [usersRes, ordersRes, paymentsRes, commissionsRes] = await Promise.all([
          db.from('sp_users').select('id', { count: 'exact', head: true }).in('role', ['CUSTOMER', 'B2B_CLIENT']),
          db.from('sp_policy_orders').select('id', { count: 'exact', head: true }),
          db.from('sp_payments').select('paid_amount').eq('status', 'PAID'),
          db.from('sp_commissions').select('commission_amount'),
        ]);
        const totalPembayaranMasuk = ((paymentsRes.data ?? []) as any[]).reduce((s: number, p: any) => s + (p.paid_amount ?? 0), 0);
        const totalKomisiAgen = ((commissionsRes.data ?? []) as any[]).reduce((s: number, c: any) => s + (c.commission_amount ?? 0), 0);
        return json({ data: { totalCustomers: usersRes.count ?? 0, totalOrders: ordersRes.count ?? 0, totalPembayaranMasuk, totalKomisiAgen } });
      }

    case 'create_policy_order': {
        if (!caller.spUser) return json({ error: 'No profile' }, 403);
        const p = params as Record<string, any>;

        // FIX: agents must be verified before they can create orders.
        // Previously this check was missing — unverified agents could submit orders
        // and they would sit in the operator queue (verification was cosmetic).
        if (caller.spUser.role === 'AGENT' && caller.spUser.verified === false) {
          return json({ error: 'Akun agen Anda belum diverifikasi. Tunggu konfirmasi dari operator atau hubungi tim SurePath.' }, 403);
        }

        // Required fields.
        if (!p.client_name || !p.product_code || !p.product_name || !p.coverage_type || !p.status) {
          return json({ error: 'client_name, product_code, product_name, coverage_type, status required' }, 400);
        }

        // Server-side validation: core premium fields must be positive numbers.
        const POSITIVE_NUM = ['base_premium', 'total_premium'];
        for (const k of POSITIVE_NUM) {
          const v = Number(p[k]);
          if (!Number.isFinite(v) || v <= 0) {
            return json({ error: `${k} must be a positive number` }, 400);
          }
        }
        // Other numeric fields (when present) must be non-negative.
        const NON_NEGATIVE_NUM = ['addon_premium', 'admin_fee', 'stamp_duty', 'sum_insured', 'discount_amount', 'commission_amount', 'coin_reward', 'net_premium'];
        for (const k of NON_NEGATIVE_NUM) {
          if (k in p && p[k] != null) {
            const v = Number(p[k]);
            if (!Number.isFinite(v) || v < 0) {
              return json({ error: `${k} must be a non-negative number` }, 400);
            }
          }
        }

        // Server-side vehicle-age-vs-insurer-limit check. The client (agent
        // wizard) already filters this, but that's advisory only — re-verify
        // here so it can't be bypassed by calling the gateway directly with a
        // stale/edited payload. Silently skipped when no insurer is chosen yet
        // or the vehicle year isn't present (e.g. non-vehicle products).
        if (p.insurer_id && p.vehicle_type && p.vehicle_details?.year) {
          const vehicleAge = new Date().getFullYear() - Number(p.vehicle_details.year);
          const { data: matchingProducts } = await db
            .from('sp_insurer_products')
            .select('max_vehicle_age_years, vehicle_coverage')
            .eq('insurer_id', p.insurer_id)
            .eq('product_type', p.vehicle_type)
            .eq('is_active', true)
            .or(`vehicle_coverage.eq.${p.coverage_type},vehicle_coverage.eq.ALL`);
          // Prefer the exact coverage-type match over a generic "ALL" row.
          const matchingProduct = (matchingProducts ?? []).find((r: any) => r.vehicle_coverage === p.coverage_type)
            ?? (matchingProducts ?? [])[0];
          const maxAge = matchingProduct?.max_vehicle_age_years;
          if (maxAge && vehicleAge > maxAge) {
            return json({ error: `Kendaraan berusia ${vehicleAge} tahun melebihi batas maksimal ${maxAge} tahun untuk insurer ini.` }, 400);
          }
        }

        // ── Siapa nasabah order ini ────────────────────────────────────────
        //
        // Sebelumnya client_id hanya terisi kalau nasabah memesan sendiri, jadi
        // order yang dijual agen menyimpan nasabahnya sebagai teks saja dan
        // client_id-nya NULL selamanya. Akibatnya nasabah tidak melihat polisnya
        // di /custapp, dan submit_claim menolaknya dengan 403 atas polis yang
        // memang miliknya.
        //
        // Dicocokkan lewat email saja, dan agen yang mengisi emailnya sendiri
        // tidak bisa menjadi client atas ordernya sendiri. Aturan lengkapnya —
        // dan alasan nomor telepon tidak dipakai — ada di clientLink.ts.
        const resolvedClientId = caller.spUser.role === 'CUSTOMER'
          ? caller.spUser.id
          : await findClientIdByEmail(db, p.client_email, caller.ownerIds);

        // FIX v1.44.0 (pentest C1+C4): Replace `...rest` spread with strict allowlist.
        // Previously, agents could inject `status:'ISSUED'`, `commission_amount:999999999`,
        // `policy_number`, `policy_document_url`, `client_id`, etc. — bypassing review,
        // self-awarding unlimited commission, and creating fake policies.
        // Now: only safe fields are accepted; all sensitive fields are server-computed.
        const insertRow: Record<string, unknown> = {
          agent_id: caller.spUser.id,           // owner — never trust the client
          // FIX v1.50.0: customer self-service orders also record client_id so
          // payments/claims ownership checks (client_id = caller) work. Still
          // server-derived — never taken from the request payload.
          client_id: resolvedClientId,
          status: 'SUBMITTED',                   // force — never trust client status
          client_name:       String(p.client_name ?? '').slice(0, 200),
          client_phone:      p.client_phone      ? String(p.client_phone).slice(0, 30)    : null,
          client_email:      p.client_email      ? String(p.client_email).slice(0, 200)   : null,
          client_ktp:        p.client_ktp        ? String(p.client_ktp).slice(0, 50)      : null,
          product_code:      String(p.product_code ?? '').slice(0, 50),
          product_name:      String(p.product_name ?? '').slice(0, 200),
          coverage_type:     String(p.coverage_type ?? '').slice(0, 30),
          vehicle_type:      p.vehicle_type      ? String(p.vehicle_type).slice(0, 30)    : null,
          vehicle_details:   p.vehicle_details   ? p.vehicle_details                       : null,
          sum_insured:       Number(p.sum_insured ?? 0),
          base_premium:      Number(p.base_premium ?? 0),
          addon_premium:     Number(p.addon_premium ?? 0),
          total_premium:     Number(p.total_premium ?? 0),
          net_premium:       Number(p.net_premium ?? Number(p.total_premium ?? 0)),
          admin_fee:         Number(p.admin_fee ?? 0),
          stamp_duty:        Number(p.stamp_duty ?? 0),
          application_fee:   Number(p.application_fee ?? 0),
          zone:              p.zone != null ? Number(p.zone) : null,
          insurer_id:        p.insurer_id        ? String(p.insurer_id)                    : null,
          addons:            p.addons            ? p.addons                                : null,
          ai_findings:       p.ai_findings       ? p.ai_findings                           : null,
          agent_code:        p.agent_code        ? String(p.agent_code).slice(0, 50)      : null,
          // commission_amount, coin_reward, discount_rate, discount_amount are set below (server-side)
          // policy_number, policy_document_url, reviewed_at, issued_at, client_id — NEVER accepted from client
        };

        // ── Server-side commission computation (fixes C1) ──────────────────
        // Previously: commission_amount was client-controlled → agent could self-award
        // unlimited IDR. Now: compute from insurer product config × total_premium.
        let serverCommissionRate = 0.10; // default 10%
        let serverCoinRate = 0;          // default 0 coins per IDR
        if (p.insurer_id) {
          const { data: insProd } = await db.from('sp_insurer_products')
            .select('base_commission_rate, coin_rate')
            .eq('insurer_id', String(p.insurer_id))
            .eq('product_type', p.vehicle_type ?? 'CAR')
            .eq('is_active', true)
            .or(`vehicle_coverage.eq.${p.coverage_type},vehicle_coverage.eq.ALL`)
            .maybeSingle();
          if (insProd) {
            serverCommissionRate = Number(insProd.base_commission_rate ?? 0.10);
            serverCoinRate = Number(insProd.coin_rate ?? 0);
          }
        }
        // Also check agent's own commission_rate from sp_users (capped at 30%)
        const { data: agentRow } = await db.from('sp_users')
          .select('commission_rate')
          .eq('id', caller.spUser.id)
          .maybeSingle();
        if (agentRow?.commission_rate != null) {
          serverCommissionRate = Math.min(Number(agentRow.commission_rate), 0.30); // cap at 30%
        }
        const computedCommission = Math.round(Number(p.total_premium ?? 0) * serverCommissionRate);
        // coin_rate is the reward-value rate; 1 coin represents Rp1,000 (matches admin fallback and ledger rp_value).
        const computedCoinReward = Math.floor(Number(p.total_premium ?? 0) * serverCoinRate / 1000);
        insertRow.commission_amount = computedCommission;
        insertRow.commission_rate   = serverCommissionRate;
        insertRow.coin_reward       = computedCoinReward;
        // Sanity ceiling: commission cannot exceed total_premium
        if (computedCommission > Number(p.total_premium ?? 0) * 2) {
          return json({ error: 'Komisi melebihi batas wajar. Hubungi admin.' }, 400);
        }

        // ── Server-side promo code validation ───────────────────────────────
        // SECURITY: The client sends discount_rate + discount_amount in the
        // payload. Without this check, a user could bypass the promo code UI
        // and just send discount_rate: 0.25 directly. We re-validate the code
        // server-side and override the discount fields with the authoritative
        // values from sp_promo_codes.
        //
        // If no promoCode is provided but discount_rate > 0, we zero it out
        // (no discount without a valid code).
        const clientDiscountRate = Number(p.discount_rate ?? 0);
        const clientPromoCode = String(p.promoCode ?? p.promo_code ?? '').trim().toUpperCase();

        if (clientPromoCode) {
          // Validate the code against sp_promo_codes
          const { data: promoRow } = await db
            .from('sp_promo_codes')
            .select('code, discount_type, discount_value, min_premium, usage_limit, used_count, valid_from, valid_to, is_active')
            .eq('code', clientPromoCode)
            .eq('is_active', true)
            .maybeSingle();

          if (!promoRow) {
            return json({ error: `Kode promo "${clientPromoCode}" tidak valid atau sudah tidak aktif` }, 400);
          }

          // Check date range (existing schema: valid_from / valid_to)
          const now = new Date();
          if (new Date(promoRow.valid_from) > now) {
            return json({ error: 'Kode promo belum berlaku' }, 400);
          }
          if (promoRow.valid_to && new Date(promoRow.valid_to) < now) {
            return json({ error: 'Kode promo sudah kedaluwarsa' }, 400);
          }
          // Check usage limit (existing schema: usage_limit / used_count)
          if (promoRow.usage_limit !== null && promoRow.used_count >= promoRow.usage_limit) {
            return json({ error: 'Kuota kode promo sudah habis' }, 400);
          }
          // Check minimum premium
          const orderTotal = Number(p.total_premium ?? 0);
          if (Number(promoRow.min_premium) > 0 && orderTotal < Number(promoRow.min_premium)) {
            return json({ error: `Minimum pembelian Rp ${Number(promoRow.min_premium).toLocaleString('id-ID')} untuk kode promo ini` }, 400);
          }

          // Override the discount fields with the authoritative values
          // SECURITY: fetch the insurer's max_discount_rate and clamp the
          // promo discount to it — prevents a malicious client from bypassing
          // the UI cap by sending a higher discount_rate directly.
          let insurerMaxDiscount = 1; // default: no cap (100%)
          if (p.insurer_id) {
            const { data: insurerProduct } = await db
              .from('sp_insurer_products')
              .select('max_discount_rate')
              .eq('insurer_id', p.insurer_id)
              .eq('product_type', p.vehicle_type ?? 'CAR')
              .eq('is_active', true)
              .or(`vehicle_coverage.eq.${p.coverage_type},vehicle_coverage.eq.ALL`)
              .maybeSingle();
            if (insurerProduct?.max_discount_rate != null) {
              insurerMaxDiscount = Number(insurerProduct.max_discount_rate);
            }
          }

          if (promoRow.discount_type === 'PERCENT') {
            // Cap at: min(promo_value, insurer_max_discount)
            const promoRate = Number(promoRow.discount_value) / 100;
            const validatedDiscountRate = Math.min(promoRate, insurerMaxDiscount);
            insertRow.discount_rate = validatedDiscountRate;
            insertRow.discount_amount = Math.round(orderTotal * validatedDiscountRate);
          } else {
            // NOMINAL — fixed IDR amount
            const nominalDiscount = Number(promoRow.discount_value);
            insertRow.discount_rate = orderTotal > 0 ? nominalDiscount / orderTotal : 0;
            insertRow.discount_amount = Math.min(nominalDiscount, orderTotal);
          }
          insertRow.promo_code = promoRow.code;
        } else if (clientDiscountRate > 0) {
          // No promo code but client sent a discount — zero it out
          console.warn(`[data-gateway] create_policy_order: caller ${caller.authId} sent discount_rate=${clientDiscountRate} without a promo code — zeroing out`);
          insertRow.discount_rate = 0;
          insertRow.discount_amount = 0;
        }

        const { data, error } = await db.from('sp_policy_orders').insert(insertRow).select().single();
        if (error) return json({ error: error.message }, 400);

        // FIX v1.44.0 (pentest C3): Atomically increment promo code used_count.
        // Previously: used_count was checked but never incremented → unlimited redemptions.
        // Now: after successful order insert, increment used_count atomically.
        if (clientPromoCode) {
          const { error: promoIncErr } = await db.from('sp_promo_codes')
            .update({ used_count: db.rpc('increment', { x: 1 }) })
            .eq('code', clientPromoCode);
          // Fallback: if RPC not available, do a raw SQL increment
          if (promoIncErr) {
            await db.rpc('increment_promo_used_count', { p_code: clientPromoCode }).then(() => {}, () => {});
          }
        }

        // Admin Telegram + insurer email alerts (non-blocking)
        const order     = data as Record<string, any>;
        const orderTime = new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' });
        const premiumStr = order.total_premium
          ? `Rp ${Number(order.total_premium).toLocaleString('id-ID')}`
          : '-';
        // ── Operator/admin in-app notification (for /operatorapp realtime feed) ──
        db.from('sp_admin_notifications').insert({
          type: 'NEW_ORDER',
          title: 'Pengajuan Polis Baru',
          body: `${String(order.client_name ?? '-')} · ${String(order.product_name ?? '-')} · ${premiumStr}`,
          order_id: order.id,
          read: false,
          metadata: { order_id: order.id, order_number: order.order_number, status: order.status },
        }).then(() => {}, () => {});
        sendTelegram(
          `Order Polis Baru - SurePath\n\n` +
          `No. Order: ${order.order_number ?? order.id}\n` +
          `Nasabah: ${order.client_name ?? '-'}\n` +
          `Produk: ${order.product_name ?? '-'}\n` +
          `Premi: ${premiumStr}\n` +
          `Status: ${order.status ?? '-'}\n` +
          `Waktu: ${orderTime} WIB\n\n` +
          `Buka Admin Panel: https://myinsurepath.com/admin`
        );
        // NOTE: Insurer review link is NOT sent here. It's sent only after
        // operator approves the order (via admin_send_insurer_review_link
        // action called from OperatorOrders.handleApprove). Sending it here
        // would notify the insurer before SurePath has reviewed the order.

        return json({ data });
      }

    case 'get_my_payments': {
        if (!caller.spUser) return json({ error: 'No profile' }, 403);
        // FIX v1.50.0: previously matched client_id only (which was never set)
        // → payments were invisible to everyone. Now: owned orders are those
        // where the caller is the agent OR the client. Admins may pass
        // order_ids to fetch payments for arbitrary orders.
        let orderIds: string[];
        const requestedIds = Array.isArray(params.order_ids)
          ? (params.order_ids as unknown[]).map(String).slice(0, 200)
          : null;
        if (caller.isAdmin && requestedIds) {
          orderIds = requestedIds;
        } else {
          const ownerFilter = caller.ownerIds
            .flatMap((id) => [`agent_id.eq.${id}`, `client_id.eq.${id}`])
            .join(',');
          const { data: myOrders, error: ordErr } = await db
            .from('sp_policy_orders')
            .select('id')
            .or(ownerFilter);
          if (ordErr) return json({ error: ordErr.message }, 400);
          orderIds = (myOrders ?? []).map((o: any) => String(o.id));
          if (requestedIds) orderIds = orderIds.filter((id) => requestedIds.includes(id));
        }
        if (orderIds.length === 0) return json({ data: [] });
        const { data, error } = await db
          .from('sp_payments')
          .select('*')
          .in('order_id', orderIds)
          .is('deleted_at', null)
          .order('created_at', { ascending: false });
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    default:
      return null; // Not handled by this module
  }
}

// quotations.ts — e-quotation actions (3 actions)
//
// Backs the QR code printed on every quotation slip PDF:
//   save_quotation            (authed)  — snapshot a generated quotation
//   get_public_quotation      (public)  — load the e-quotation page by code
//   confirm_public_quotation  (public)  — customer signals intent to proceed
//
// The public confirm is an intent signal only; binding confirmation always
// remains with the insurer (stated on the PDF and the e-quotation page).

import type { GatewayContext, ActionResult } from './types.ts';

const json = (body: unknown, status = 200): ActionResult => ({ status, body });

// Payload fields safe to expose on the public e-quotation page. The stored
// payload is a full QuotationSlipData snapshot; chassis/engine numbers and
// address stay server-side.
const PUBLIC_PAYLOAD_FIELDS = [
  'quotationNumber', 'slipType', 'issueDate', 'productName', 'productLine',
  'preparedForCompany', 'insurer', 'insurerShort', 'insurerLogoUrl',
  'periodStart', 'periodEnd', 'objectSummary',
  'coverageCondition', 'additionalCoverage', 'deductible', 'klausulList',
  'sumInsuredItems', 'totalSumInsured', 'currency',
  'premiumComponents', 'subtotalPremium', 'discountLabel', 'discountAmount',
  'premiumAfterDiscount', 'policyFee', 'stampDuty', 'totalPremium',
  'subjectivityList', 'termsList',
  'bankName', 'bankAccount', 'bankAccountName', 'paymentDueDate', 'transferMemo',
  'agentName', 'agentPhone', 'validUntil',
];

function publicPayload(payload: Record<string, unknown> | null): Record<string, unknown> {
  const src = payload ?? {};
  const out: Record<string, unknown> = {};
  for (const k of PUBLIC_PAYLOAD_FIELDS) {
    if (src[k] !== undefined) out[k] = src[k];
  }
  return out;
}

export async function handleQuotationsAction(action: string, ctx: GatewayContext): Promise<ActionResult | null> {
  const { db, params, caller, checkRateLimit } = ctx;

  switch (action) {
    // ── save_quotation (authed) ─────────────────────────────────────────────
    // Upserts by code so re-downloading the same quotation refreshes the
    // snapshot instead of duplicating rows.
    case 'save_quotation': {
      if (!caller.spUser) return json({ error: 'No profile' }, 403);
      const allowed = await checkRateLimit(`user:${caller.spUser.id}`, 60);
      if (!allowed) return json({ error: 'Rate limit exceeded. Coba lagi dalam 1 jam.' }, 429);

      const code = String(params.code ?? '').trim();
      const payload = (params.payload ?? {}) as Record<string, unknown>;
      const quotationNumber = String(params.quotation_number ?? payload.quotationNumber ?? '').trim();
      if (!/^[A-Za-z0-9_-]{8,40}$/.test(code)) return json({ error: 'Invalid quotation code' }, 400);
      if (!quotationNumber) return json({ error: 'Missing quotation number' }, 400);

      const row = {
        code,
        quotation_number: quotationNumber,
        product_type: String(params.product_type ?? 'MOTOR').slice(0, 20),
        product_name: params.product_name ? String(params.product_name).slice(0, 120) : null,
        payload,
        customer_name: params.customer_name ? String(params.customer_name).slice(0, 120) : null,
        insurer_name: params.insurer_name ? String(params.insurer_name).slice(0, 120) : null,
        agent_name: params.agent_name ? String(params.agent_name).slice(0, 120) : null,
        agent_phone: params.agent_phone ? String(params.agent_phone).slice(0, 32) : null,
        total_premium: typeof params.total_premium === 'number' ? params.total_premium : null,
        valid_until: params.valid_until ? String(params.valid_until).slice(0, 10) : null,
        source_app: params.source_app ? String(params.source_app).slice(0, 20) : null,
        created_by: caller.spUser.id,
        order_id: params.order_id ? String(params.order_id) : null,
        // QR link lives 14 days from (re)generation — re-downloading the PDF
        // refreshes the window. Separate from valid_until (commercial validity).
        link_expires_at: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString(),
        updated_at: new Date().toISOString(),
      };

      const { data, error } = await db
        .from('sp_quotations')
        .upsert(row, { onConflict: 'code' })
        .select('id, code')
        .single();
      if (error) return json({ error: error.message }, 500);
      return json({ data });
    }

    // ── get_public_quotation (public, rate-limited by IP in index.ts) ──────
    case 'get_public_quotation': {
      const code = String(params.code ?? '').trim();
      if (!/^[A-Za-z0-9_-]{8,40}$/.test(code)) return json({ error: 'Invalid quotation code' }, 400);

      const { data: q, error } = await db
        .from('sp_quotations')
        .select('code, quotation_number, product_type, product_name, status, payload, customer_name, insurer_name, agent_name, agent_phone, total_premium, valid_until, link_expires_at, confirmed_at, created_at')
        .eq('code', code)
        .maybeSingle();
      if (error) return json({ error: error.message }, 500);
      if (!q) return json({ error: 'Quotation not found' }, 404);

      // First open marks it viewed (best-effort, non-blocking)
      if (q.status === 'SENT') {
        db.from('sp_quotations')
          .update({ status: 'VIEWED', viewed_at: new Date().toISOString(), updated_at: new Date().toISOString() })
          .eq('code', code)
          .then(() => {}, () => {});
      }

      // Expired when the commercial validity passed OR the 14-day QR link
      // window (link_expires_at, null on pre-migration rows) has closed.
      const expired =
        (q.valid_until ? new Date(q.valid_until + 'T23:59:59') < new Date() : false) ||
        (q.link_expires_at ? new Date(q.link_expires_at) < new Date() : false);
      return json({
        data: {
          code: q.code,
          quotation_number: q.quotation_number,
          product_type: q.product_type,
          product_name: q.product_name,
          status: expired && q.status !== 'CONFIRMED' && q.status !== 'PAID' ? 'EXPIRED' : q.status,
          customer_name: q.customer_name,
          insurer_name: q.insurer_name,
          agent_name: q.agent_name,
          agent_phone: q.agent_phone,
          total_premium: q.total_premium,
          valid_until: q.valid_until,
          link_expires_at: q.link_expires_at,
          confirmed_at: q.confirmed_at,
          created_at: q.created_at,
          payload: publicPayload(q.payload),
        },
      });
    }

    // ── confirm_public_quotation (public, rate-limited by IP in index.ts) ──
    case 'confirm_public_quotation': {
      const code = String(params.code ?? '').trim();
      if (!/^[A-Za-z0-9_-]{8,40}$/.test(code)) return json({ error: 'Invalid quotation code' }, 400);
      const name = String(params.name ?? '').trim().slice(0, 120);
      const phone = String(params.phone ?? '').trim().slice(0, 32);
      if (!name) return json({ error: 'Nama wajib diisi' }, 400);

      const { data: q, error } = await db
        .from('sp_quotations')
        .select('id, code, quotation_number, status, customer_name, agent_name, total_premium, valid_until, link_expires_at')
        .eq('code', code)
        .maybeSingle();
      if (error) return json({ error: error.message }, 500);
      if (!q) return json({ error: 'Quotation not found' }, 404);
      if (q.status === 'PAID') return json({ error: 'Quotation sudah dibayar' }, 409);
      if (
        (q.valid_until && new Date(q.valid_until + 'T23:59:59') < new Date()) ||
        (q.link_expires_at && new Date(q.link_expires_at) < new Date())
      ) {
        return json({ error: 'Quotation sudah kedaluwarsa. Hubungi agen/tim SurePath untuk penawaran baru.' }, 410);
      }

      const { error: updErr } = await db
        .from('sp_quotations')
        .update({
          status: 'CONFIRMED',
          confirmed_at: new Date().toISOString(),
          confirmed_name: name,
          confirmed_phone: phone || null,
          updated_at: new Date().toISOString(),
        })
        .eq('code', code);
      if (updErr) return json({ error: updErr.message }, 500);

      ctx.sendTelegram(
        `✅ <b>E-Quotation dikonfirmasi</b>\n` +
        `No: ${q.quotation_number}\n` +
        `Nasabah: ${name}${phone ? ` (${phone})` : ''}\n` +
        `Agen: ${q.agent_name ?? '-'}\n` +
        `Premi: ${q.total_premium ?? '-'}\n` +
        `https://myinsurepath.com/q/${q.code}`
      );

      return json({ data: { ok: true, status: 'CONFIRMED' } });
    }

    default:
      return null;
  }
}

// tiers.ts — Agent tier definitions, assignment, and approval workflow.
import type { GatewayContext, ActionResult } from './types.ts';

const json = (body: unknown, status = 200): ActionResult => ({ status, body });

const TIER_ASSIGNERS = ['MASTER_ADMIN', 'ADMIN', 'FINANCE_MANAGER'];
const TIER_STRUCTURE_ADMINS = ['MASTER_ADMIN', 'ADMIN'];

async function computeAgentMetrics(db: any, agentId: string) {
  const [ordersRes, commissionsRes] = await Promise.all([
    db.from('sp_policy_orders').select('id', { count: 'exact', head: true }).eq('agent_id', agentId).eq('status', 'ISSUED'),
    db.from('sp_commissions').select('premium_amount').eq('agent_id', agentId),
  ]);
  const totalPremium = ((commissionsRes.data ?? []) as any[]).reduce((s, c) => s + Number(c.premium_amount ?? 0), 0);
  return { policiesCount: ordersRes.count ?? 0, totalPremium };
}

// Find the highest-rank active tier whose thresholds are met by the given metrics.
function resolveEligibleTier(tiers: any[], policiesCount: number, totalPremium: number) {
  const eligible = tiers
    .filter(t => t.is_active)
    .filter(t => (t.min_policies_count == null || policiesCount >= t.min_policies_count)
              && (t.min_premium_amount == null || totalPremium >= t.min_premium_amount))
    .sort((a, b) => b.rank - a.rank);
  return eligible[0] ?? tiers.find(t => t.is_default) ?? null;
}

// Applies a tier to an agent, or queues an approval request if the target
// tier requires it and the caller isn't a qualifying approver.
async function applyOrQueueTier(
  db: any, agentId: string, targetTier: any, currentTierCode: string | null,
  callerId: string, callerRole: string, source: 'MANUAL' | 'AUTO', reason?: string,
): Promise<{ pending: boolean; data: unknown }> {
  const isDowngrade = currentTierCode
    ? (await db.from('sp_agent_tiers').select('rank').eq('code', currentTierCode).maybeSingle()).data?.rank > targetTier.rank
    : false;
  const needsApproval = isDowngrade || (targetTier.requires_approval && !(targetTier.approval_roles ?? []).includes(callerRole));

  if (needsApproval) {
    const { data, error } = await db.from('sp_tier_change_requests').insert({
      agent_id: agentId,
      requested_tier_code: targetTier.code,
      current_tier_code: currentTierCode,
      requested_by: callerId || null,
      reason: reason ?? null,
      source: source === 'AUTO' ? 'AUTO_ELIGIBLE' : 'MANUAL_REQUEST',
    }).select().maybeSingle();
    if (error) throw new Error(error.message);
    return { pending: true, data };
  }

  const { error: updErr } = await db.from('sp_users').update({ tier: targetTier.code, tier_assigned_by: callerId || null, tier_assigned_at: new Date().toISOString() }).eq('id', agentId);
  if (updErr) throw new Error(updErr.message);
  await db.from('sp_agent_tier_history').insert({
    agent_id: agentId, tier_code: targetTier.code, previous_tier_code: currentTierCode,
    source, assigned_by: callerId || null, note: reason ?? null,
  });
  return { pending: false, data: { agent_id: agentId, tier: targetTier.code } };
}

export async function handleTiersAction(action: string, ctx: GatewayContext): Promise<ActionResult | null> {
  const { db, params, caller } = ctx;

  switch (action) {
    case 'get_tier_definitions': {
        if (!caller.spUser) return json({ error: 'Unauthorized' }, 401);
        const { data, error } = await db.from('sp_agent_tiers').select('*').eq('is_active', true).order('rank', { ascending: true });
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'get_my_tier_progress': {
        if (!caller.spUser) return json({ error: 'Unauthorized' }, 401);
        const agentId = caller.spUser.id;
        const [{ data: tiers }, metrics] = await Promise.all([
          db.from('sp_agent_tiers').select('*').eq('is_active', true).order('rank', { ascending: true }),
          computeAgentMetrics(db, agentId),
        ]);
        const allTiers = tiers ?? [];
        const currentTier = allTiers.find((t: any) => t.code === caller.spUser?.tier) ?? null;
        const nextTier = allTiers.find((t: any) => t.rank === (currentTier?.rank ?? -1) + 1) ?? null;
        return json({ data: { currentTier, nextTier, ...metrics } });
      }

    case 'admin_list_tiers': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        const { data, error } = await db.from('sp_agent_tiers').select('*').order('rank', { ascending: true });
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'admin_create_tier': {
        if (!TIER_STRUCTURE_ADMINS.includes(caller.role ?? '')) return json({ error: 'Forbidden: only MASTER_ADMIN/ADMIN can create tiers' }, 403);
        if (!params.code || !params.name) return json({ error: 'code and name required' }, 400);
        const insertRow: Record<string, unknown> = {
          code: String(params.code).toUpperCase().trim(),
          name: String(params.name),
          rank: Number(params.rank ?? 0),
          color: params.color ? String(params.color) : '#6b7280',
          emoji: params.emoji ? String(params.emoji) : null,
          min_policies_count: params.min_policies_count != null ? Number(params.min_policies_count) : null,
          min_premium_amount: params.min_premium_amount != null ? Number(params.min_premium_amount) : null,
          coin_bonus_rate: Number(params.coin_bonus_rate ?? 0),
          l1_override_rate: Number(params.l1_override_rate ?? 0),
          l2_override_rate: Number(params.l2_override_rate ?? 0),
          benefits: params.benefits ?? {},
          requires_approval: Boolean(params.requires_approval),
          approval_roles: params.approval_roles ?? ['MASTER_ADMIN'],
          is_active: params.is_active !== false,
          updated_by: caller.authId || null,
        };
        const { data, error } = await db.from('sp_agent_tiers').insert(insertRow).select().maybeSingle();
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'admin_update_tier': {
        if (!TIER_STRUCTURE_ADMINS.includes(caller.role ?? '')) return json({ error: 'Forbidden: only MASTER_ADMIN/ADMIN can edit tiers' }, 403);
        if (!params.code) return json({ error: 'code required' }, 400);
        const ALLOWED = ['name', 'rank', 'color', 'emoji', 'min_policies_count', 'min_premium_amount', 'coin_bonus_rate', 'l1_override_rate', 'l2_override_rate', 'benefits', 'requires_approval', 'approval_roles', 'is_active', 'is_default'];
        const updates: Record<string, unknown> = { updated_at: new Date().toISOString(), updated_by: caller.authId || null };
        for (const k of ALLOWED) { if (k in params) updates[k] = params[k]; }
        if (Object.keys(updates).length === 2) return json({ error: 'No valid fields to update' }, 400);

        // Only one default tier — clear the others first if this one is being set as default.
        if (updates.is_default === true) {
          await db.from('sp_agent_tiers').update({ is_default: false }).neq('code', params.code);
        }
        const { data, error } = await db.from('sp_agent_tiers').update(updates).eq('code', params.code).select().maybeSingle();
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'admin_delete_tier': {
        if (!TIER_STRUCTURE_ADMINS.includes(caller.role ?? '')) return json({ error: 'Forbidden: only MASTER_ADMIN/ADMIN can delete tiers' }, 403);
        if (!params.code) return json({ error: 'code required' }, 400);
        const { count } = await db.from('sp_users').select('id', { count: 'exact', head: true }).eq('tier', params.code);
        if ((count ?? 0) > 0) return json({ error: `Tidak bisa dihapus: ${count} agen masih memiliki tier ini. Pindahkan mereka dahulu.` }, 400);
        const { error } = await db.from('sp_agent_tiers').update({ is_active: false }).eq('code', params.code);
        if (error) return json({ error: error.message }, 400);
        return json({ data: { success: true } });
      }

    case 'admin_reorder_tiers': {
        if (!TIER_STRUCTURE_ADMINS.includes(caller.role ?? '')) return json({ error: 'Forbidden: only MASTER_ADMIN/ADMIN can reorder tiers' }, 403);
        const order = params.order as Array<{ code: string; rank: number }> | undefined;
        if (!Array.isArray(order) || order.length === 0) return json({ error: 'order array required' }, 400);
        for (const { code, rank } of order) {
          await db.from('sp_agent_tiers').update({ rank, updated_at: new Date().toISOString() }).eq('code', code);
        }
        return json({ data: { success: true } });
      }

    case 'admin_assign_agent_tier': {
        if (!TIER_ASSIGNERS.includes(caller.role ?? '')) return json({ error: 'Your role is not permitted to assign tiers' }, 403);
        if (!params.agent_id || !params.tier_code) return json({ error: 'agent_id and tier_code required' }, 400);
        const [{ data: targetTier }, { data: agentRow }] = await Promise.all([
          db.from('sp_agent_tiers').select('*').eq('code', String(params.tier_code)).eq('is_active', true).maybeSingle(),
          db.from('sp_users').select('tier').eq('id', String(params.agent_id)).maybeSingle(),
        ]);
        if (!targetTier) return json({ error: 'Tier tidak ditemukan atau nonaktif' }, 404);
        try {
          const result = await applyOrQueueTier(db, String(params.agent_id), targetTier, agentRow?.tier ?? null, caller.authId, caller.role ?? '', 'MANUAL', params.reason ? String(params.reason) : undefined);
          return json({ data: result.data, pending: result.pending });
        } catch (e) {
          return json({ error: (e as Error).message }, 400);
        }
      }

    case 'admin_list_tier_requests': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        let q = db.from('sp_tier_change_requests').select('*, sp_users!agent_id(name, email, agent_code)').order('requested_at', { ascending: false }).limit(Number(params.limit ?? 200));
        if (params.status) q = q.eq('status', String(params.status));
        const { data, error } = await q;
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'admin_approve_tier_request': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        if (!params.request_id) return json({ error: 'request_id required' }, 400);
        const { data: reqRow, error: reqErr } = await db.from('sp_tier_change_requests').select('*').eq('id', params.request_id).maybeSingle();
        if (reqErr || !reqRow) return json({ error: 'Request not found' }, 404);
        if (reqRow.status !== 'PENDING') return json({ error: 'Request sudah diproses' }, 400);
        const { data: targetTier } = await db.from('sp_agent_tiers').select('*').eq('code', reqRow.requested_tier_code).maybeSingle();
        if (!targetTier) return json({ error: 'Tier target tidak ditemukan' }, 404);
        if (targetTier.requires_approval && !(targetTier.approval_roles ?? []).includes(caller.role ?? '')) {
          return json({ error: 'Role Anda tidak berwenang menyetujui tier ini' }, 403);
        }

        const ts = new Date().toISOString();
        await db.from('sp_users').update({ tier: targetTier.code, tier_assigned_by: caller.authId, tier_assigned_at: ts }).eq('id', reqRow.agent_id);
        await db.from('sp_agent_tier_history').insert({
          agent_id: reqRow.agent_id, tier_code: targetTier.code, previous_tier_code: reqRow.current_tier_code,
          source: reqRow.source === 'AUTO_ELIGIBLE' ? 'AUTO' : 'MANUAL', assigned_by: caller.authId, note: 'Disetujui via antrean persetujuan',
        });
        const { data, error } = await db.from('sp_tier_change_requests').update({ status: 'APPROVED', approved_by: caller.authId, approved_at: ts, updated_at: ts }).eq('id', params.request_id).select().maybeSingle();
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'admin_reject_tier_request': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        if (!params.request_id) return json({ error: 'request_id required' }, 400);
        const ts = new Date().toISOString();
        const { data, error } = await db.from('sp_tier_change_requests').update({
          status: 'REJECTED', rejected_by: caller.authId, rejected_at: ts,
          rejection_reason: params.reason ? String(params.reason) : null, updated_at: ts,
        }).eq('id', params.request_id).eq('status', 'PENDING').select().maybeSingle();
        if (error) return json({ error: error.message }, 400);
        if (!data) return json({ error: 'Request not found or already processed' }, 404);
        return json({ data });
      }

    case 'admin_evaluate_agent_tier': {
        if (!TIER_ASSIGNERS.includes(caller.role ?? '')) return json({ error: 'Your role is not permitted to evaluate tiers' }, 403);
        if (!params.agent_id) return json({ error: 'agent_id required' }, 400);
        const [{ data: tiers }, metrics, { data: agentRow }] = await Promise.all([
          db.from('sp_agent_tiers').select('*'),
          computeAgentMetrics(db, String(params.agent_id)),
          db.from('sp_users').select('tier').eq('id', String(params.agent_id)).maybeSingle(),
        ]);
        const suggested = resolveEligibleTier(tiers ?? [], metrics.policiesCount, metrics.totalPremium);
        if (!suggested) return json({ error: 'Tidak ada tier aktif untuk dievaluasi' }, 400);
        if (suggested.code === agentRow?.tier) return json({ data: { changed: false, tier: suggested.code, metrics } });
        if (!params.apply) return json({ data: { changed: true, suggested_tier: suggested.code, current_tier: agentRow?.tier ?? null, metrics } });
        try {
          const result = await applyOrQueueTier(db, String(params.agent_id), suggested, agentRow?.tier ?? null, caller.authId, caller.role ?? '', 'AUTO');
          return json({ data: { ...result.data, metrics }, pending: result.pending });
        } catch (e) {
          return json({ error: (e as Error).message }, 400);
        }
      }

    case 'admin_evaluate_all_agents': {
        if (!TIER_ASSIGNERS.includes(caller.role ?? '')) return json({ error: 'Your role is not permitted to evaluate tiers' }, 403);
        const [{ data: tiers }, { data: agents }] = await Promise.all([
          db.from('sp_agent_tiers').select('*'),
          db.from('sp_users').select('id, tier').eq('role', 'AGENT'),
        ]);
        let applied = 0, queued = 0, unchanged = 0;
        for (const agent of (agents ?? [])) {
          const metrics = await computeAgentMetrics(db, agent.id);
          const suggested = resolveEligibleTier(tiers ?? [], metrics.policiesCount, metrics.totalPremium);
          if (!suggested || suggested.code === agent.tier) { unchanged++; continue; }
          try {
            const result = await applyOrQueueTier(db, agent.id, suggested, agent.tier ?? null, caller.authId, caller.role ?? '', 'AUTO');
            if (result.pending) queued++; else applied++;
          } catch { /* skip agent on error, continue batch */ }
        }
        return json({ data: { total: (agents ?? []).length, applied, queued, unchanged } });
      }

    default:
      return null;
  }
}

// Gateway domain modules — shared types and helpers.
// Each module receives GatewayContext and returns ActionResult | null.

export interface GatewayContext {
  db: any;
  params: Record<string, any>;
  caller: {
    authId: string;
    email: string;
    spUser: Record<string, any> | null;
    role: string | null;
    isAdmin: boolean;
    isFinanceAdmin: boolean;  // FIX v1.44.0: excludes OPERATOR — for commission/wallet actions
    userMetadata: Record<string, any> | null;
    // FIX v1.50.0: canonical owner id — sp_users.id when the profile exists,
    // else auth.users.id. Legacy accounts (pre-ensure_profile) have
    // sp_users.id ≠ auth.users.id; rows are written with sp_users.id, so all
    // "my data" reads must use this, never authId directly.
    ownerId: string;
    // Both ids, deduped — for reads that must also match legacy rows written
    // with authId (e.g. sp_claims.user_id, sp_notifications.agent_id).
    ownerIds: string[];
  };
  sendTelegram: (text: string) => void;
  logActivity: (insurerId: string | null, orderId: string | null, action: string, details?: Record<string, unknown>) => void;
  checkRateLimit: (identifier: string, limit: number) => Promise<boolean>;
  RESEND_KEY: string;
}

export interface ActionResult {
  status: number;
  body: unknown;
}

export const ok = (data: unknown): ActionResult => ({ status: 200, body: { data } });
export const err = (message: string, status = 400): ActionResult => ({ status, body: { error: message } });

// users.ts — 10 actions
// Auto-generated from data-gateway/index.ts split
import type { GatewayContext, ActionResult } from './types.ts';
import { isUntrustedEmail } from '../../_shared/trust.ts';
import { linkOrdersToNewCustomer } from './clientLink.ts';

// json() helper — returns ActionResult (main index.ts converts to Response)
const json = (body: unknown, status = 200): ActionResult => ({ status, body });

export async function handleUsersAction(action: string, ctx: GatewayContext): Promise<ActionResult | null> {
  // Only the context fields this module actually uses. The generated split
  // destructured all of them; the unused names are dead weight (and tsc flags
  // them now that the unit tests pull this module into the type program).
  const { db, params, caller, sendTelegram } = ctx;

  switch (action) {
    case 'get_my_profile': {
        if (!caller.spUser) return json({ error: 'No SurePath profile linked to this account' }, 404);
        return json({ data: caller.spUser });
      }

    case 'accept_agreement': {
        if (!caller.spUser) return json({ error: 'No profile' }, 403);
        const fullName = String(params.full_name ?? '').trim();
        const ktpNumber = String(params.ktp_number ?? '').trim();
        if (fullName.length < 3) return json({ error: 'Name too short' }, 400);
        if (!/^[0-9]{16}$/.test(ktpNumber)) return json({ error: 'KTP must be 16 digits' }, 400);

        const { data: existing } = await db
          .from('sp_agent_agreements')
          .select('id')
          .in('agent_id', caller.ownerIds)
          .eq('doc_version', 'v1.0-2026')
          .maybeSingle();
        if (existing) return json({ error: 'ALREADY_ACCEPTED' }, 409);

        const { data: agreement, error: agErr } = await db
          .from('sp_agent_agreements')
          .insert({
            agent_id: caller.ownerId,
            doc_version: 'v1.0-2026',
            full_name: fullName,
            ktp_number: ktpNumber,
            user_agent: String(params.user_agent ?? '').slice(0, 255) || null,
          })
          .select()
          .single();
        if (agErr) {
          console.error('accept_agreement error:', agErr);
          return json({ error: agErr.message }, 400);
        }
        return json({ data: agreement });
      }

    case 'get_my_agreement': {
        if (!caller.spUser) return json({ data: null });
        const { data: ag } = await db
          .from('sp_agent_agreements')
          .select('*')
          .in('agent_id', caller.ownerIds)
          .eq('doc_version', 'v1.0-2026')
          .maybeSingle();
        return json({ data: ag ?? null });
      }

    case 'ensure_profile': {
        // ROLE STICKINESS INVARIANT (v1.52.0):
        // Once a user has a profile row, their role is IMMUTABLE through this
        // endpoint. If the client sends a role param that disagrees with the
        // stored role, we ignore the param and return the stored profile.
        // The only path to change a role is admin_update_user (audited).
        //
        // FIX v1.49.2: Handle Google OAuth login for existing users.
        // When a user registers with email/password, sp_users.id = auth.users.id.
        // When they later login with Google, Supabase creates a NEW auth.users.id
        // (different UUID). The .or(id, email) lookup in index.ts should find
        // the existing row by email, but if it doesn't (case sensitivity, timing),
        // we need to explicitly look up by email and UPDATE the id to match
        // the new auth ID, rather than INSERTING a duplicate row.
        const reqRoleRaw = String(params.role ?? '').toUpperCase();

        if (caller.spUser) {
          if (reqRoleRaw && reqRoleRaw !== String(caller.spUser.role ?? '').toUpperCase()) {
            console.warn(
              `[ensure_profile] role-change attempt ignored — user=${caller.authId} ` +
              `stored=${caller.spUser.role} requested=${reqRoleRaw} email=${caller.email}`
            );
          }
          return json({ data: caller.spUser, existed: true });
        }

        // Pertahanan berlapis — HANYA untuk profil baru.
        //
        // Sengaja diletakkan SESUDAH cabang "profil sudah ada" di atas.
        // ensure_profile dipanggil di SETIAP login, jadi menolak lebih awal
        // akan mengunci enam akun berdomain mencurigakan yang sudah terlanjur
        // ada di produksi — pengguna lama tidak boleh terdampak, prinsip yang
        // sama dengan grandfathering di _shared/trust.ts.
        //
        // Validasi di klien bisa dilewati dengan memanggil API langsung, jadi
        // pendaftaran baru tetap diperiksa di sini.
        if (isUntrustedEmail(caller.email)) {
          return json({
            error: 'Gunakan alamat email sungguhan — domain tersebut tidak bisa menerima email.',
            code: 'UNTRUSTED_EMAIL_DOMAIN',
          }, 403);
        }

        // Explicit email lookup — case insensitive
        const { data: existingByEmail } = await db.from('sp_users')
          .select('*')
          .ilike('email', caller.email)
          .maybeSingle();

        if (existingByEmail) {
          if (reqRoleRaw && reqRoleRaw !== String(existingByEmail.role ?? '').toUpperCase()) {
            console.warn(
              `[ensure_profile] role-change attempt ignored (by-email) — user=${caller.authId} ` +
              `stored=${existingByEmail.role} requested=${reqRoleRaw} email=${caller.email}`
            );
          }
          // User already exists (registered with email/password, now logging
          // in with Google). Update their auth ID to the new Google auth ID
          // so future lookups work correctly. Preserve all existing data,
          // ESPECIALLY the role — never touch it here.
          const { data: updated, error: updErr } = await db.from('sp_users')
            .update({
              id: caller.authId,
              updated_at: new Date().toISOString(),
            })
            .eq('id', existingByEmail.id)
            .select()
            .maybeSingle();

          if (updErr) {
            // If update fails (e.g. FK constraint), return the existing profile
            // with the old ID — the app will still work for this session
            console.warn('ensure_profile: failed to update auth ID:', updErr.message);
            return json({ data: existingByEmail, existed: true });
          }
          if (updated) return json({ data: updated, existed: true });
          return json({ data: existingByEmail, existed: true });
        }

        // No existing user — create new profile.
        //
        // The account type must be stated, never assumed. This used to fall
        // back to 'CUSTOMER' when neither the caller nor the signup metadata
        // named a role, so any client that called ensure_profile without one
        // silently minted a customer — which is exactly how brand-new Google/
        // OTP signups skipped the account-type picker and landed in the
        // customer app. Refusing here keeps that from being reintroduced by a
        // future caller; the client is expected to answer with a role
        // (RoleSelectionScreen) and call again.
        const meta = (caller.userMetadata ?? {}) as Record<string, unknown>;
        const metaRoleRaw = String(meta.role ?? '').toUpperCase();
        const reqRole = reqRoleRaw || metaRoleRaw;
        if (!reqRole) {
          return json({
            error: 'ROLE_REQUIRED: account type must be chosen before a profile can be created',
            code: 'ROLE_REQUIRED',
          }, 409);
        }
        const role = reqRole === 'AGENT' ? 'AGENT' : 'CUSTOMER';
        const insertRow: Record<string, unknown> = {
          id: caller.authId,
          email: caller.email,
          name: String(params.name ?? meta.name ?? caller.email.split('@')[0]),
          phone: String(params.phone ?? meta.phone ?? ''),
          ktp: params.ktp ?? meta.ktp ?? null,
          address: params.address ?? meta.address ?? null,
          role,
          trust_score: role === 'AGENT' ? 80 : 85,
          verified: role !== 'AGENT',
          agent_code: role === 'AGENT'
            ? 'SP-AGT-' + String(Math.floor(1000 + Math.random() * 9000))
            : 'SP-' + String(Math.floor(Math.random() * 99999)).padStart(5, '0'),
        };
        if (role === 'AGENT') {
          insertRow.commission_rate = 0.1;
          insertRow.monthly_target = 50000000;
        }
        // Referral linkage — code travels in signup metadata (survives the
        // email-confirmation flow, even on another device) or explicit param.
        // Matches the upline's agent_code OR referral_code.
        // SECURITY: sanitize the ref code before interpolating into a PostgREST
        // .or() string — otherwise a value like "xyz,id.eq.<admin_uuid>" would
        // extend the filter and match arbitrary rows (filter injection).
        const rawRefCode = String(params.referral_code ?? meta.referral_code ?? '').trim();
        const refCode = rawRefCode.replace(/[^A-Za-z0-9-]/g, '').slice(0, 32);
        if (refCode) {
          // SECURITY: refCode is sanitized (alphanumeric + dash only, max 32 chars)
          // so it's safe to interpolate into the PostgREST .or() string filter.
          // The array form .or([{...}, {...}]) is NOT supported by the Supabase
          // JS client — it only accepts a string. Using the array form causes a
          // silent crash that breaks registration.
          const { data: upline } = await db
            .from('sp_users')
            .select('id')
            .or(`agent_code.eq.${refCode},referral_code.eq.${refCode}`)
            .neq('id', caller.authId)
            .maybeSingle();
          if (upline) insertRow.upline_id = upline.id;
        }
        const { data, error } = await db.from('sp_users').insert(insertRow).select().single();
        if (error) return json({ error: error.message }, 400);

        // ── Polis yang sudah dijual sebelum nasabahnya punya akun ──────────
        //
        // Agen menjual, nasabah mendaftar belakangan. Tanpa langkah ini
        // ordernya tetap tidak bertuan dan /custapp-nya kosong meski polisnya
        // ada. Emailnya dari sesi yang sudah diverifikasi, bukan dari params,
        // dan hanya order yang belum bertuan yang disentuh — aturan lengkapnya
        // di clientLink.ts.
        let linkedOrders = 0;
        if (role === 'CUSTOMER') {
          linkedOrders = await linkOrdersToNewCustomer(db, String((data as any).id), caller.email);
          if (linkedOrders > 0) {
            console.log(`[ensure_profile] ${linkedOrders} order ditautkan ke nasabah baru ${(data as any).id}`);
          }
        }

        // Auto-notify admins of new registration (non-blocking, best-effort)
        const roleLabel = role === 'AGENT' ? 'Agen' : 'Customer';
        db.from('sp_admin_notifications').insert({
          type: `NEW_${role}`,
          title: `${roleLabel} Baru Mendaftar`,
          body: `${String(insertRow.name)} (${caller.email}) baru saja mendaftar sebagai ${roleLabel.toLowerCase()}.`,
          read: false,
          metadata: { user_id: (data as any).id, role, email: caller.email },
        }).then(() => {}, () => {});
        // Telegram push to admin team
        const tgTime = new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' });
        sendTelegram(
          `Akun ${roleLabel} Baru - SurePath\n\n` +
          `Nama: ${String(insertRow.name)}\n` +
          `Email: ${caller.email}\n` +
          `HP: ${String(insertRow.phone) || '-'}\n` +
          `Waktu: ${tgTime} WIB\n\n` +
          `Buka Admin Panel: https://myinsurepath.com/admin`
        );
        return json({ data, existed: false, linked_orders: linkedOrders });
      }

    case 'apply_referral': {
        if (!caller.spUser) return json({ error: 'No profile' }, 403);
        // SECURITY: sanitize the code — PostgREST .or() string interpolation
        // is otherwise vulnerable to filter injection.
        const rawCode = String(params.code ?? '').trim();
        const code = rawCode.replace(/[^A-Za-z0-9-]/g, '').slice(0, 32);
        if (!code) return json({ error: 'Missing code' }, 400);
        if (caller.spUser.upline_id) return json({ data: { upline_id: caller.spUser.upline_id, already_set: true } });
        const { data: upline, error: lookupErr } = await db
          .from('sp_users')
          .select('id')
          .or(`agent_code.eq.${code},referral_code.eq.${code}`)
          .neq('id', caller.spUser.id)
          .maybeSingle();
        if (lookupErr) return json({ error: lookupErr.message }, 400);
        if (!upline) return json({ error: 'Invalid referral code' }, 404);
        const { error } = await db
          .from('sp_users')
          .update({ upline_id: upline.id, updated_at: new Date().toISOString() })
          .eq('id', caller.spUser.id);
        if (error) return json({ error: error.message }, 400);
        return json({ data: { upline_id: upline.id } });
      }

    case 'list_my_clients': {
        if (!caller.spUser) return json({ error: 'No profile' }, 403);
        const agentId = caller.isAdmin && params.agent_id ? params.agent_id : caller.spUser.id;
        const { data, error } = await db.from('sp_clients').select('*').eq('agent_id', agentId);
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'update_fcm_token': {
        if (!caller.spUser) return json({ error: 'No profile' }, 403);
        const token = String(params.token ?? '').trim();
        if (!token) return json({ error: 'Missing token' }, 400);
        const { error: updErr } = await db
          .from('sp_users')
          .update({ fcm_token: token, updated_at: new Date().toISOString() })
          .eq('id', caller.spUser.id);
        if (updErr) return json({ error: updErr.message }, 400);
        return json({ data: { ok: true } });
      }

    case 'update_my_profile': {
        if (!caller.spUser) return json({ error: 'No profile' }, 403);
        const SAFE = ['name', 'phone', 'address', 'profile_photo_url', 'ktp_document_url'];
        const updates: Record<string, unknown> = { updated_at: new Date().toISOString() };
        for (const k of SAFE) {
          if (k in params) updates[k] = params[k];
        }
        const { data, error } = await db.from('sp_users').update(updates).eq('id', caller.spUser.id).select().maybeSingle();
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'get_user_profile': {
        if (!caller.spUser) return json({ error: 'No profile' }, 403);
        const targetId = params.user_id ? String(params.user_id) : caller.spUser.id;
        if (targetId !== caller.spUser.id && !caller.isAdmin) return json({ error: 'Forbidden' }, 403);
        const { data, error } = await db.from('sp_users').select('id, email, name, phone, role, agent_code, tier, verified, commission_rate, created_at').eq('id', targetId).maybeSingle();
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'record_tc_acceptance': {
        if (!caller.spUser) return json({ error: 'No profile' }, 403);
        const refNumber = `TC-${new Date().getFullYear()}-${String(Math.floor(Math.random() * 1000000)).padStart(6, '0')}`;
        const { error: tcErr } = await db.from('sp_tnc_records').insert({
          user_id: caller.spUser.id,
          reference_number: refNumber,
          tnc_version: String(params.tnc_version ?? 'v1.0'),
          accepted_at: new Date().toISOString(),
        });
        if (tcErr) return json({ error: tcErr.message }, 400);
        // Update sp_users tc_accepted fields
        await db.from('sp_users').update({
          tc_accepted: true,
          tc_accepted_at: new Date().toISOString(),
          tnc_ref_number: refNumber,
        }).eq('id', caller.spUser.id);
        return json({ data: { reference_number: refNumber } });
      }

    default:
      return null; // Not handled by this module
  }
}

// wallet.ts — 7 actions
// Auto-generated from data-gateway/index.ts split
import type { GatewayContext, ActionResult } from './types.ts';

// json() helper — returns ActionResult (main index.ts converts to Response)
const json = (body: unknown, status = 200): ActionResult => ({ status, body });

export async function handleWalletAction(action: string, ctx: GatewayContext): Promise<ActionResult | null> {
  const { db, params, caller, sendTelegram, logActivity, checkRateLimit, RESEND_KEY } = ctx;

  switch (action) {
    case 'get_agent_stats': {
        if (!caller.spUser) return json({ error: 'No profile' }, 403);
        const agentId = caller.isAdmin && params.agent_id ? params.agent_id : caller.spUser.id;
        const [commRes, clientRes, policyRes] = await Promise.all([
          db.from('sp_commissions').select('commission_amount, status, created_at').eq('agent_id', agentId),
          db.from('sp_clients').select('id', { count: 'exact', head: true }).eq('agent_id', agentId),
          db.from('sp_policies').select('id', { count: 'exact', head: true }).eq('agent_id', agentId).eq('status', 'ACTIVE'),
        ]);
        return json({ data: { commissions: commRes.data ?? [], clientCount: clientRes.count ?? 0, activePolicies: policyRes.count ?? 0 } });
      }

    case 'admin_list_withdrawals': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        let q = db.from('sp_withdrawals')
          .select('*, sp_users!agent_id(name, email, phone)')
          .order('created_at', { ascending: false })
          .limit(Number(params.limit ?? 200));
        if (params.status) q = q.eq('status', params.status);
        const { data, error } = await q;
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'admin_approve_withdrawal': {
        // FIX v2.6.18 (audit 2026-10-23, C2): the approval level is derived from
        // the withdrawal row, never from the request.
        //
        // This used to read `level` out of params and fall through an `else`
        // branch that set status: 'APPROVED' unconditionally — so level 3, 0 or
        // "x" (NaN) all approved any amount in one call, with no check that the
        // row was even awaiting approval and no check that L1/L2 had happened.
        // The <10jt/>=10jt/>=25jt ladder was effectively not enforced at all.
        //
        // On roles (owner's call, 2026-10-23): *every* tier is finance-only.
        // OPERATOR sits in ADMIN_ROLES but not FINANCE_ROLES, so an operator can
        // no longer sign any tier, not even L1 on a <10jt request. The operator
        // portal's L1 button was removed in the same change
        // (components/operator/OperatorWithdrawals.tsx); operators keep read
        // access to the queue and keep rejecting, which only reverses a
        // deduction the agent already made.
        if (!caller.isFinanceAdmin) {
          return json({ error: 'Forbidden: withdrawal approval requires a finance admin' }, 403);
        }
        if (!params.withdrawal_id) return json({ error: 'withdrawal_id required' }, 400);

        const { data: wd, error: fetchErr } = await db.from('sp_withdrawals')
          .select('amount, status, l1_approved_by, l2_approved_by')
          .eq('id', params.withdrawal_id)
          .single();
        if (fetchErr || !wd) return json({ error: 'Withdrawal not found' }, 404);

        const STAGE_OF: Record<string, number> = { PENDING_L1: 1, PENDING_L2: 2, PENDING_L3: 3 };
        const stage = STAGE_OF[String(wd.status)];
        if (!stage) return json({ error: 'Withdrawal is not awaiting approval' }, 409);

        // Tiers required by amount, mirroring agent_request_withdrawal below.
        const required = (wd.amount ?? 0) >= 25_000_000 ? 3 : (wd.amount ?? 0) >= 10_000_000 ? 2 : 1;

        // Four-eyes: nobody may sign the same withdrawal twice.
        if ([wd.l1_approved_by, wd.l2_approved_by].includes(caller.authId)) {
          return json({ error: 'Approval requires a different approver' }, 403);
        }

        const ts = new Date().toISOString();
        const updates: Record<string, unknown> = {
          updated_at: ts,
          [`l${stage}_approved_by`]: caller.authId,
          [`l${stage}_approved_at`]: ts,
          status: stage >= required ? 'APPROVED' : `PENDING_L${stage + 1}`,
        };

        // .eq('status', wd.status) makes this an atomic claim of the stage we
        // read, so two approvers racing cannot both advance the same step.
        const { data, error } = await db.from('sp_withdrawals')
          .update(updates)
          .eq('id', params.withdrawal_id)
          .eq('status', wd.status)
          .select()
          .maybeSingle();
        if (error) return json({ error: error.message }, 400);
        if (!data) return json({ error: 'Withdrawal state changed, please retry' }, 409);
        return json({ data });
      }

    case 'admin_reject_withdrawal': {
        // Left on isAdmin deliberately: rejecting only reverses a deduction the
        // agent already made, it cannot release funds, and the operator portal
        // owns this queue (services/operatorService.ts `rejectWithdrawal`).
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        // FIX v1.44.0 (pentest M5): use caller.authId instead of client-supplied rejector_id.
        if (!params.withdrawal_id || !params.reason) {
          return json({ error: 'withdrawal_id, reason required' }, 400);
        }
        const { data: wd, error: fetchErr } = await db.from('sp_withdrawals').select('agent_id, amount').eq('id', params.withdrawal_id).single();
        if (fetchErr || !wd) return json({ error: 'Withdrawal not found' }, 404);
        const { error: updErr } = await db.from('sp_withdrawals').update({
          status: 'REJECTED', rejected_by: caller.authId,
          rejected_at: new Date().toISOString(), rejection_reason: params.reason,
          updated_at: new Date().toISOString(),
        }).eq('id', params.withdrawal_id);
        if (updErr) return json({ error: updErr.message }, 400);
        await db.rpc('reverse_withdrawal', {
          p_withdrawal_id: params.withdrawal_id, p_agent_id: wd.agent_id,
          p_amount: wd.amount, p_reason: 'Penarikan ditolak: ' + String(params.reason),
        });
        return json({ data: { success: true } });
      }

    case 'award_coins': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        if (!params.agent_id || !params.coins || !params.order_id) return json({ error: 'agent_id, coins, order_id required' }, 400);
        const coins = Number(params.coins);
        const { error } = await db.from('sp_coin_ledger').insert({
          agent_id: params.agent_id,
          type: 'EARNED',
          coins,
          rp_value: coins * 1000,
          order_id: params.order_id,
          description: params.description ?? 'Komisi polis',
        });
        if (error) return json({ error: error.message }, 400);
        await db.rpc('increment_coins_balance', { p_agent_id: params.agent_id, p_delta: coins });
        return json({ data: { success: true } });
      }

    case 'redeem_coins': {
        if (!caller.spUser) return json({ error: 'No profile' }, 403);
        // FIX v1.42.0: add verified check (consistent with create_policy_order + agent_request_withdrawal)
        if (caller.spUser.role === 'AGENT' && caller.spUser.verified === false) {
          return json({ error: 'Akun agen Anda belum diverifikasi.' }, 403);
        }
        const coins = Number(params.coins);
        if (!coins || coins <= 0) return json({ error: 'coins must be positive' }, 400);
        const { data: ledger } = await db.from('sp_coin_ledger').select('type, coins').eq('agent_id', caller.spUser.id);
        const balance = (ledger ?? []).reduce((s: number, r: any) => s + (r.type === 'REDEEMED' ? -Math.abs(Number(r.coins) || 0) : Number(r.coins) || 0), 0);
        if (balance < coins) return json({ error: 'Insufficient balance' }, 400);
        const { error } = await db.from('sp_coin_ledger').insert({
          agent_id: caller.spUser.id,
          type: 'REDEEMED',
          coins: -Math.abs(coins),
          rp_value: -(coins * 1000),
          description: params.description ?? 'Pencairan koin',
        });
        if (error) return json({ error: error.message }, 400);
        await db.rpc('increment_coins_balance', { p_agent_id: caller.spUser.id, p_delta: -coins });
        return json({ data: { success: true } });
      }

    case 'get_leaderboard': {
        if (!caller.spUser) return json({ error: 'No profile' }, 403);
        const now = new Date();
        const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1).toISOString();
        const { data: commData, error: commErr } = await db.from('sp_commissions')
          .select('agent_id, commission_amount')
          .eq('status', 'PAID')
          .gte('created_at', startOfMonth);
        if (commErr) return json({ error: commErr.message }, 400);
        const map: Record<string, number> = {};
        (commData ?? []).forEach((r: any) => { map[r.agent_id] = (map[r.agent_id] ?? 0) + (r.commission_amount ?? 0); });
        const agentIds = Object.keys(map);
        if (agentIds.length === 0) return json({ data: [] });
        const { data: users } = await db.from('sp_users').select('id, name, agent_code, tier').in('id', agentIds);
        const userMap: Record<string, { name: string; agent_code: string; tier: string | null }> = {};
        (users ?? []).forEach((u: any) => { userMap[u.id] = { name: u.name, agent_code: u.agent_code ?? '', tier: u.tier ?? null }; });
        const result = agentIds
          .map(id => ({ agent_id: id, agent_name: userMap[id]?.name ?? 'Agent', agent_code: userMap[id]?.agent_code ?? '', tier: userMap[id]?.tier ?? null, total_commission: map[id] }))
          .sort((a, b) => b.total_commission - a.total_commission)
          .slice(0, 10);
        return json({ data: result });
      }

    // ─── New: agent_request_withdrawal (fixes withdrawal bypass + verified check) ──
    // Previously services/wallet.ts requestWithdrawal() called supabase directly with user JWT,
    // bypassing the gateway entirely. RLS on sp_withdrawals only checks auth.uid() = agent_id,
    // NOT verified status — so unverified agents could submit withdrawal requests.
    // This action enforces: (1) caller is AGENT, (2) caller is verified, (3) amount > Xendit fee,
    // (4) atomic wallet deduction via request_withdrawal_deduct RPC.
    case 'agent_request_withdrawal': {
        if (!caller.spUser) return json({ error: 'No profile' }, 403);
        if (caller.spUser.role !== 'AGENT') return json({ error: 'Hanya agen yang dapat melakukan penarikan' }, 403);
        if (caller.spUser.verified === false) {
          return json({ error: 'Akun agen Anda belum diverifikasi. Penarikan tidak diizinkan.' }, 403);
        }

        const amount = Number(params.amount ?? 0);
        const bankCode = String(params.bank_code ?? '').slice(0, 20);
        const accountNumber = String(params.account_number ?? '').slice(0, 50);
        const accountHolderName = String(params.account_holder_name ?? '').slice(0, 200);

        if (amount <= 0) return json({ error: 'Jumlah harus lebih besar dari 0' }, 400);
        if (!bankCode || !accountNumber || !accountHolderName) {
          return json({ error: 'bank_code, account_number, account_holder_name wajib diisi' }, 400);
        }

        const XENDIT_FEE = 5000;
        const net_amount = amount - XENDIT_FEE;
        if (net_amount <= 0) return json({ error: 'Jumlah terlalu kecil setelah biaya transfer' }, 400);

        // Determine required approval level
        let initial_status: string;
        if (amount >= 25_000_000) initial_status = 'PENDING_L3';
        else if (amount >= 10_000_000) initial_status = 'PENDING_L2';
        else initial_status = 'PENDING_L1';

        const scheduled_disburse_at = amount >= 25_000_000
          ? new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
          : null;

        const { data: wd, error: wdErr } = await db
          .from('sp_withdrawals')
          .insert({
            agent_id: caller.authId,
            amount,
            bank_code: bankCode,
            account_number: accountNumber,
            account_holder_name: accountHolderName,
            xendit_fee: XENDIT_FEE,
            net_amount,
            status: initial_status,
            scheduled_disburse_at,
          })
          .select('id')
          .single();

        if (wdErr || !wd) return json({ error: wdErr?.message ?? 'Gagal membuat penarikan' }, 400);

        // Atomically deduct wallet via RPC (SECURITY DEFINER)
        const { error: deductErr } = await db.rpc('request_withdrawal_deduct', {
          p_withdrawal_id: wd.id,
          p_agent_id:      caller.authId,
          p_amount:        amount,
        });

        if (deductErr) {
          // Rollback withdrawal insert
          await db.from('sp_withdrawals').update({ status: 'CANCELLED' }).eq('id', wd.id);
          return json({ error: deductErr.message }, 400);
        }

        return json({ data: { success: true, withdrawal_id: wd.id } });
      }

    default:
      return null; // Not handled by this module
  }
}
